if (!ctx) {
        hermes_log(LOG_WARNING, "port", "aux_interrupt_protection: null context");
        return false;
    }
    hermes_log(LOG_DEBUG, "port", "aux_interrupt_protection called");
    return aux_interrupt_protection(active ? true : false);

if (!url) return NULL;

    char resp_path[256];
    snprintf(resp_path, sizeof(resp_path),
             "/tmp/billing_resp_%d_%ld.json", getpid(), (long)time(NULL));

    /* Build curl command */
    char cmd[8192];
    int n;
    if (auth_header && *auth_header) {
        n = snprintf(cmd, sizeof(cmd),
            "curl -s -w '\\n%%{http_code}' -X GET '%s' "
            "-H 'Authorization: %s' "
            "-H 'Accept: application/json' "
            "> '%s' 2>/dev/null",
            url, auth_header, resp_path);
    } else {
        n = snprintf(cmd, sizeof(cmd),
            "curl -s -w '\\n%%{http_code}' -X GET '%s' "
            "-H 'Accept: application/json' "
            "> '%s' 2>/dev/null",
            url, resp_path);
    }

    if (n < 0 || (size_t)n >= sizeof(cmd)) {
        unlink(resp_path);
        return strdup("{\"error\":\"command too long\"}");
    }

    int ret = system(cmd);
    if (ret != 0) {
        unlink(resp_path);
        return strdup("{\"error\":\"curl command failed\"}");
    }

    /* Read response */
    FILE *f = fopen(resp_path, "r");
    if (!f) {
        return strdup("{\"error\":\"failed to read response\"}");
    }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (fsize <= 0 || fsize > 1024 * 1024) {
        fclose(f);
        unlink(resp_path);
        return strdup("{\"error\":\"invalid response size\"}");
    }

    char *buf = malloc(fsize + 1);
    if (!buf) {
        fclose(f);
        unlink(resp_path);
        return strdup("{\"error\":\"oom\"}");
    }
    fread(buf, 1, fsize, f);
    buf[fsize] = '\0';
    fclose(f);
    unlink(resp_path);

    /* Split body and HTTP code (last line) */
    char *last_nl = strrchr(buf, '\n');
    if (last_nl) {
        *last_nl = '\0';
    }
    return buf;

