        execl("/bin/sh", "sh", "-c", cmd, (char *)NULL);
        _exit(127);
    }

    close(out_pipe[1]);
    char buf[4096];
    ssize_t total = 0;
    ssize_t n;
    while ((n = read(out_pipe[0], buf, sizeof(buf) - 1)) > 0) {
        if ((size_t)total + (size_t)n < response_size - 1) {
            memcpy(response_out + total, buf, (size_t)n);
            total += n;
        }
