    int j = 0;
    int in_space = 0;
    for (const char *p = text; *p; p++) {
        if (*p == ' ' || *p == '\t') {
            if (!in_space && j > 0) {
                result[j++] = ' ';
                in_space = 1;
            }
        } else {
            result[j++] = (char)toupper((unsigned char)*p);
            in_space = 0;
        }
    }

