    char *start = buf;
    while (*start && (*start == ' ' || *start == '\t' ||
                      *start == '\n' || *start == '\r')) start++;
    char *end = start + strlen(start);
    while (end > start && (end[-1] == ' ' || end[-1] == '\t' ||
                          end[-1] == '\n' || end[-1] == '\r')) end--;
    *end = '\0';
    memmove(buf, start, strlen(start) + 1);
    /* lower */
    for (char *p = buf; *p; p++) *p = tolower((unsigned char)*p);
    return buf;

