        "(?<!\\*)\\*(?!\\*| )(.+?)(?<!\\*)\\*(?!\\*)", "(?<!\\w)_(?!_)(.+?)(?<!_)_(?!\\w)"
    };
    const char *sty[6] = { "BOLD","BOLD","STRIKETHROUGH","MONOSPACE","ITALIC","ITALIC" };
    typedef struct { int ms, me, g1s, g1e; int pi; } im_t;
    im_t *all = NULL; int na = 0, acap = 0;
