    size_t body_len = json_body ? strlen(json_body) : 0;
    char *escaped = malloc(body_len * 2 + 1);
    if (!escaped) return strdup("{\"error\":\"oom\"}");
    size_t j = 0;
    for (size_t i = 0; i < body_len; i++) {
        if (json_body[i] == '\'' || json_body[i] == '\"' || json_body[i] == '\\' || json_body[i] == '$' || json_body[i] == '`') {
            escaped[j++] = '\\';
