    char cmd[16384];
    int n = snprintf(cmd, sizeof(cmd),
        "curl -s -w '\\n%%{http_code}' -X POST '%s' "
        "-H 'Content-Type: application/json' "
        "-H 'Authorization: %s' "
        "-d '%s' "
        "> '%s' 2>/dev/null",
        url, auth_header ? auth_header : "", escaped, resp_path);
