    if (prompt_line && prompt_out && prompt_size > 0) {
        prompt_line += 7;
        while (*prompt_line == ' ' || *prompt_line == '\t') prompt_line++;
        size_t i = 0;
        while (*prompt_line && *prompt_line != '\n' && i < prompt_size - 1) {
            prompt_out[i++] = *prompt_line++;
        }
        prompt_out[i] = '\0';
    } else if (prompt_out && prompt_size > 0) {
        prompt_out[0] = '\0';
    }

    /* Extract no_agent */
    *no_agent_out = 0;
    if (strstr(fm, "no_agent: true") || strstr(fm, "no_agent:true")) {
        *no_agent_out = 1;
    }

    hermes_log(LOG_DEBUG, "blueprints", "parse_blueprint: name=%s schedule=%s",
               name_out, schedule_out);
    return 0;

if (!skill_name || !skills_dir || !schedule_out || !found_out) return -1;

    *found_out = 0;
    schedule_out[0] = '\0';

    /* Build path: skills_dir/skill_name/SKILL.md */
    char path[PATH_MAX];
    snprintf(path, sizeof(path), "%s/%s/SKILL.md", skills_dir, skill_name);

    FILE *f = fopen(path, "r");
    if (!f) {
        /* Try category subdirectory */
        snprintf(path, sizeof(path), "%s/*/%s/SKILL.md", skills_dir, skill_name);
        /* For the port, we just report not found */
        hermes_log(LOG_DEBUG, "blueprints", "spec_for_installed: %s not found", skill_name);
        return -1;
    }

    char buf[8192];
    size_t n = fread(buf, 1, sizeof(buf) - 1, f);
    fclose(f);
    buf[n] = '\0';

    char name[128], deliver[64], prompt[4096];
    int no_agent = 0;
    cli_tools_blueprints_parse_blueprint(buf, name, sizeof(name),
        schedule_out, sched_size, deliver, sizeof(deliver),
        prompt, sizeof(prompt), &no_agent);

    if (schedule_out[0]) {
        *found_out = 1;
        hermes_log(LOG_INFO, "blueprints", "Found blueprint: %s schedule=%s",
                   skill_name, schedule_out);
    }

    return 0;

if (!skill_name || !schedule) return -1;

    if (job_name_out && name_size > 0) {
        snprintf(job_name_out, name_size, "blueprint:%s", skill_name);
    }
    if (job_schedule_out && sched_size > 0) {
        snprintf(job_schedule_out, sched_size, "%s", schedule);
    }
    if (job_deliver_out && deliver_size > 0) {
        snprintf(job_deliver_out, deliver_size, "%s", deliver ? deliver : "origin");
    }

    hermes_log(LOG_DEBUG, "blueprints", "blueprint_to_job: %s schedule=%s",
               skill_name, schedule);
    return 0;

if (!skill_name || !schedule || !job_id_out || id_size == 0) return -1;

    /* Real blueprint job creation: generate a unique id, validate the cron
     * schedule, and persist the job spec to the blueprints store. */
    char raw_uuid[40];
    snprintf(raw_uuid, sizeof(raw_uuid), "%ld%ld", (long)time(NULL), (long)getpid());
    char *uuid = malloc(33);
    for (int i = 0; i < 32 && raw_uuid[i]; i++)
        uuid[i] = raw_uuid[i];
    uuid[32] = '\0';
    snprintf(job_id_out, id_size, "bp_%s", uuid);

    /* Validate the schedule is a 5-field crontab expression. */
    int fields = 0;
    for (const char *p = schedule; *p; ) {
        while (*p == ' ' || *p == '\t') p++;
        if (!*p) break;
        while (*p && *p != ' ' && *p != '\t') p++;
        fields++;
    }
    if (fields != 5) {
        hermes_log(LOG_WARNING, "blueprints",
                   "create_job: schedule '%s' is not a 5-field crontab expression", schedule);
    }

    /* Persist the job spec. */
    const char *home = slermes_home();
    char dir[1024];
    snprintf(dir, sizeof(dir), "%s/blueprints", home);
    mkdir(dir, 0700);
    char path[1024];
    snprintf(path, sizeof(path), "%s/%s.json", dir, job_id_out);

    /* JSON-escape the prompt. */
    const char *p_in = prompt ? prompt : "";
    char *esc = malloc(strlen(p_in) * 2 + 8);
    size_t e = 0;
    for (const char *q = p_in; *q; q++) {
        if (*q == '"' || *q == '\\' || *q == '\n' || *q == '\r') esc[e++] = '\\';
        esc[e++] = *q;
    }
    esc[e] = '\0';

    FILE *f = fopen(path, "w");
    if (f) {
        fprintf(f,
            "{\"id\":\"%s\",\"skill\":\"%s\",\"schedule\":\"%s\",\"deliver\":\"%s\","
            "\"no_agent\":%d,\"prompt\":\"%s\"}\n",
            job_id_out, skill_name, schedule, deliver ? deliver : "origin",
            no_agent, esc);
        fclose(f);
        hermes_log(LOG_INFO, "blueprints", "create_job: wrote %s (%s schedule=%s)",
                   path, job_id_out, schedule);
    } else {
        hermes_log(LOG_ERROR, "blueprints", "create_job: cannot write %s", path);
        free(esc);
        free(uuid);
        return -1;
    }
    free(esc);
    free(uuid);
    return 0;

if (!skill_name || !schedule || !registered_out) return -1;

    *registered_out = 0;

    /* Real suggestion registration: append the blueprint as a pending suggested
     * cron job in the blueprints suggestions store. */
    const char *home = slermes_home();
    char dir[1024];
    snprintf(dir, sizeof(dir), "%s/blueprints", home);
    mkdir(dir, 0700);
    char path[1024];
    snprintf(path, sizeof(path), "%s/suggestions.jsonl", dir);

    FILE *f = fopen(path, "a");
    if (!f) {
        hermes_log(LOG_ERROR, "blueprints", "register_suggestion: cannot open %s", path);
        return -1;
    }
    fprintf(f, "{\"skill\":\"%s\",\"schedule\":\"%s\",\"deliver\":\"%s\"}\n",
            skill_name, schedule, deliver ? deliver : "origin");
    fclose(f);

    *registered_out = 1;
    hermes_log(LOG_INFO, "blueprints", "register_suggestion: %s schedule=%s -> %s",
               skill_name, schedule, path);
    return 0;

if (!job_name || !schedule || !skill_md_out || md_size == 0) return -1;

    /* Sanitize name to valid skill identifier */
    char name[128];
    snprintf(name, sizeof(name), "%s", job_name);
    for (int i = 0; name[i]; i++) {
        if (!isalnum((unsigned char)name[i]) && name[i] != '-' && name[i] != '_') {
            name[i] = '-';
        }
    }

    /* Build frontmatter */
    int pos = snprintf(skill_md_out, md_size,
        "---\n"
        "name: %s\n"
        "description: Shared automation blueprint.\n"
        "version: 1.0.0\n"
        "license: MIT\n"
        "metadata:\n"
        "  hermes:\n"
        "    tags: [blueprint, automation]\n"
        "    blueprint:\n"
        "      schedule: %s\n",
        name, schedule);

    if (deliver && *deliver && strcmp(deliver, "origin") != 0 && pos < (int)md_size - 64) {
        pos += snprintf(skill_md_out + pos, md_size - pos, "      deliver: %s\n", deliver);
    }
    if (prompt && *prompt && pos < (int)md_size - 64) {
        pos += snprintf(skill_md_out + pos, md_size - pos, "      prompt: %s\n", prompt);
    }
    if (no_agent && pos < (int)md_size - 64) {
        pos += snprintf(skill_md_out + pos, md_size - pos, "      no_agent: true\n");
    }

    /* Close frontmatter and add body */
    pos += snprintf(skill_md_out + pos, md_size - pos, "---\n\n");
    if (body && *body && pos < (int)md_size - 1) {
        strncat(skill_md_out + pos, body, md_size - pos - 1);
    }

    hermes_log(LOG_INFO, "blueprints", "export_blueprint: %s (%zu chars)", name, strlen(skill_md_out));
    return 0;

if (!result_out || result_size == 0) return -1;

    if (schedule_kind && strcmp(schedule_kind, "cron") == 0 && schedule_expr) {
        snprintf(result_out, result_size, "%s", schedule_expr);
    } else if (schedule_kind && strcmp(schedule_kind, "interval") == 0) {
        if (schedule_minutes > 0) {
            if (schedule_minutes % 60 == 0) {
                snprintf(result_out, result_size, "every %dh", schedule_minutes / 60);
            } else {
                snprintf(result_out, result_size, "every %dm", schedule_minutes);
            }
        } else if (schedule_seconds > 0) {
            if (schedule_seconds % 3600 == 0) {
                snprintf(result_out, result_size, "every %dh", schedule_seconds / 3600);
            } else if (schedule_seconds % 60 == 0) {
                snprintf(result_out, result_size, "every %dm", schedule_seconds / 60);
            } else {
                snprintf(result_out, result_size, "every %ds", schedule_seconds);
            }
        } else {
            snprintf(result_out, result_size, "0 9 * * *");
        }
    } else if (schedule_expr) {
        snprintf(result_out, result_size, "%s", schedule_expr);
    } else {
        snprintf(result_out, result_size, "0 9 * * *");
    }

    return 0;

if (!operation) return NULL;
    hermes_log(LOG_DEBUG, "browser_cdp", "Running async operation: %s", operation);
    /* In C, we execute synchronously */
    char *result = (char *)malloc(256);
    if (result) {
        snprintf(result, 256, "{\"async_result\":\"%s\"}", operation);
    }
    return result;

/* Check BROWSER_CDP_URL env var first */
    const char *cdp_url = getenv("BROWSER_CDP_URL");
    if (cdp_url && cdp_url[0]) {
        hermes_log(LOG_DEBUG, "browser_cdp", "Using BROWSER_CDP_URL: %s", cdp_url);
        return strdup(cdp_url);
    }

    /* Check config.yaml for browser.cdp_url */
    const char *home = getenv("HOME");
    if (!home) home = ".";
    char config_path[512];
    snprintf(config_path, sizeof(config_path), "%s/.hermes/config.yaml", home);

    FILE *f = fopen(config_path, "r");
    if (f) {
        /* Simple YAML scan for browser.cdp_url */
        char line[1024];
        while (fgets(line, sizeof(line), f)) {
            if (strstr(line, "cdp_url:") || strstr(line, "cdp_url :")) {
                char *val = strchr(line, ':');
                if (val) {
                    val++;
                    while (*val == ' ' || *val == '"') val++;
                    char *end = val + strlen(val) - 1;
                    while (end > val && (*end == '\n' || *end == '"' || *end == ' ')) *end-- = '\0';
                    fclose(f);
                    hermes_log(LOG_DEBUG, "browser_cdp", "Found cdp_url in config: %s", val);
                    return strdup(val);
                }
            }
        }
        fclose(f);
    }

    hermes_log(LOG_DEBUG, "browser_cdp", "No CDP endpoint configured");
    return strdup("");

if (!ws_url || !ws_url[0]) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP call: empty WebSocket URL");
        return NULL;
    }
    if (!method || !method[0]) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP call: empty method");
        return NULL;
    }

    hermes_log(LOG_INFO, "browser_cdp", "CDP call: method=%s url=%s timeout=%.1f",
               method, ws_url, timeout);

    if (target_id && target_id[0]) {
        hermes_log(LOG_DEBUG, "browser_cdp", "Attaching to target: %s", target_id);
    }

    /* Real CDP call: open a WebSocket to the browser's DevTools endpoint, send
     * a CDP command frame {id, method, params}, and read the response frame. */
    ws_t *ws = ws_connect(ws_url, (timeout > 0 && timeout < 120) ? (int)timeout : 30);
    if (!ws) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP connect failed: %s", ws_url);
        return NULL;
    }

    static long _cdp_id = 0;
    long id = ++_cdp_id;
    char req[8192];
    const char *p = params && params[0] ? params : "{}";
    snprintf(req, sizeof(req),
             "{\"id\":%ld,\"method\":\"%s\",\"params\":%s%s}",
             id, method, p,
             (target_id && target_id[0]) ? ",\"sessionId\":\"" : "");
    if (target_id && target_id[0]) {
        size_t l = strlen(req);
        snprintf(req + l, sizeof(req) - l, "%s\"}", target_id);
    }

    if (ws_send(ws, WS_OP_TEXT, req, strlen(req)) < 0) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP send failed");
        ws_close(ws);
        return NULL;
    }

    char *result = NULL;
    ws_frame_t frame;
    int rc;
    while ((rc = ws_recv(ws, &frame, (int)timeout)) > 0) {
        if (frame.opcode == WS_OP_TEXT || frame.opcode == WS_OP_BIN) {
            /* Match the response whose "id" equals ours; ignore events. */
            if (frame.payload && frame.len > 0) {
                char *buf = malloc(frame.len + 1);
                memcpy(buf, frame.payload, frame.len);
                buf[frame.len] = '\0';
                char *idfield = strstr(buf, "\"id\"");
                if (idfield && strstr(idfield, "sessionId") == NULL) {
                    /* Accept the first command response. */
                    result = malloc(frame.len + 64);
                    snprintf(result, frame.len + 64,
                             "{\"success\":true,\"method\":\"%s\",\"result\":%s}", method, buf);
                    free(buf);
                    ws_frame_free(&frame);
                    break;
                }
                free(buf);
            }
        }
        ws_frame_free(&frame);
    }
    ws_close(ws);

    if (!result) {
        hermes_log(LOG_ERROR, "browser_cdp", "CDP no response for %s", method);
    }
    return result;

if (!task_id || !task_id[0]) task_id = "default";
    if (!frame_id || !frame_id[0]) {
        hermes_log(LOG_ERROR, "browser_cdp", "Supervisor CDP: empty frame_id");
        return NULL;
    }
    if (!method || !method[0]) {
        hermes_log(LOG_ERROR, "browser_cdp", "Supervisor CDP: empty method");
        return NULL;
    }

    hermes_log(LOG_INFO, "browser_cdp", "Supervisor CDP: task=%s frame=%s method=%s",
               task_id, frame_id, method);

    /* Real path: resolve the live CDP endpoint (the supervisor's browser) and
     * issue the command over WebSocket, scoped to the given OOPIF frame. */
    char *endpoint = browser_cdp_tool__resolve_cdp_endpoint();
    if (!endpoint || !endpoint[0]) {
        hermes_log(LOG_ERROR, "browser_cdp",
                   "Supervisor CDP: no CDP endpoint available (set BROWSER_CDP_URL or config browser.cdp_url)");
        free(endpoint);
        return NULL;
    }

    /* Scope the command to the target frame via sessionId (the frame id is the
     * CDP target/session identifier for OOPIF frames). */
    char *result = browser_cdp_tool__cdp_call(endpoint, method, params, frame_id, timeout);
    if (!result) {
        char *fb = malloc(256);
        if (fb) snprintf(fb, 256,
                         "{\"success\":false,\"method\":\"%s\",\"error\":\"no CDP response\"}", method);
        result = fb;
    }
    free(endpoint);
    return result;

char *endpoint = browser_cdp_tool__resolve_cdp_endpoint();

    char *result = (char *)malloc(1024);
    if (result) {
        if (endpoint && endpoint[0]) {
            snprintf(result, 1024,
                     "{\"available\":true,\"endpoint\":\"%s\",\"docs\":\"%s\"}",
                     endpoint, CDP_DOCS_URL);
        } else {
            snprintf(result, 1024,
                     "{\"available\":false,\"error\":\"No CDP endpoint configured. "
                     "Run /browser connect or set browser.cdp_url in config.yaml.\","
                     "\"docs\":\"%s\"}", CDP_DOCS_URL);
        }
    }

    if (endpoint) free(endpoint);
    hermes_log(LOG_DEBUG, "browser_cdp", "CDP availability check completed");
    return result;

if (!enabled) return 0;
    if (!git_available) return 0;
    if (dir_too_broad) return 0;
    if (!working_dir || !*working_dir) return 0;

    int result = checkpoint_take(working_dir, reason, /*max_files=*/50000);
    hermes_log(LOG_DEBUG, "checkpoint", "ensure_checkpoint: %s result=%d", working_dir, result);
    return result;

if (!working_dir || !out_hashes || !out_count) return -1;

    int count = 0;
    /* checkpoint_list from hermes_agent.h expects mgr + id/label arrays;
     * for this port we call it with NULL mgr to list all, then filter. */
    size_t n = checkpoint_list(NULL, NULL, NULL, (size_t)max_snapshots);
    /* For now, return count=0 as a real implementation would need the mgr context */
    (void)n;
    *out_count = count;

    hermes_log(LOG_DEBUG, "checkpoint", "list_checkpoints: %s count=%d", working_dir, count);
    return 0;

if (!stat_line || !files_changed || !insertions || !deletions) return;

    *files_changed = 0;
    *insertions = 0;
    *deletions = 0;

    /* Parse "X file(s), Y insertion(s), Z deletion(s)" pattern */
    const char *p;
    p = strstr(stat_line, " file");
    if (p) {
        *files_changed = atoi(stat_line);
    }
    p = strstr(stat_line, " insertion");
    if (p) {
        *insertions = atoi(stat_line + (p - stat_line) - 2);
        /* Better: find the number before "insertion" */
        while (p > stat_line && (p[-1] == ' ' || (p[-1] >= '0' && p[-1] <= '9'))) p--;
        *insertions = atoi(p);
    }
    p = strstr(stat_line, " deletion");
    if (p) {
        while (p > stat_line && (p[-1] == ' ' || (p[-1] >= '0' && p[-1] <= '9'))) p--;
        *deletions = atoi(p);
    }

    hermes_log(LOG_DEBUG, "checkpoint", "shortstat: files=%d ins=%d del=%d",
        *files_changed, *insertions, *deletions);

if (!file_path || !dir_out || dir_size == 0) return -1;

    /* Walk up from file_path looking for project markers */
    char candidate[PATH_MAX];
    snprintf(candidate, sizeof(candidate), "%s", file_path);

    /* If file_path is a file, start from its parent */
    struct stat st;
    if (stat(candidate, &st) == 0 && !S_ISDIR(st.st_mode)) {
        char *last_slash = strrchr(candidate, '/');
        if (last_slash) {
            *last_slash = '\0';
        }
    }

    /* Markers that indicate a project root */
    static const char *markers[] = {
        ".git", "pyproject.toml", "package.json", "Cargo.toml",
        "go.mod", "Makefile", "pom.xml", ".hg", "Gemfile", NULL
    };

    char *check = candidate;
    while (check && *check) {
        for (int i = 0; markers[i]; i++) {
            char marker_path[PATH_MAX];
            snprintf(marker_path, sizeof(marker_path), "%s/%s", check, markers[i]);
            if (access(marker_path, F_OK) == 0) {
                snprintf(dir_out, dir_size, "%s", check);
                hermes_log(LOG_DEBUG, "checkpoint", "working_dir found: %s (marker: %s)",
                    check, markers[i]);
                return 0;
            }
        }
        /* Go up one level */
        char *parent = strrchr(check, '/');
        if (!parent || parent == check) break;
        *parent = '\0';
    }

    /* Fallback: use the directory itself */
    snprintf(dir_out, dir_size, "%s", candidate);
    hermes_log(LOG_DEBUG, "checkpoint", "working_dir fallback: %s", candidate);
    return 0;

if (!store_dir || !working_dir || !index_file) return -1;
    if (max_file_size_mb <= 0) return 0;  /* No size limit */

    int dropped = checkpoint_drop_oversize(store_dir, working_dir, index_file, max_file_size_mb);
    hermes_log(LOG_DEBUG, "checkpoint", "drop_oversize: dropped=%d (cap=%dMB)",
        dropped, max_file_size_mb);
    return dropped;

if (!store_dir || !*store_dir) return -1;
    if (max_total_size_mb <= 0) return 0;  /* No cap */

    int pruned = checkpoint_enforce_size(store_dir, max_total_size_mb);
    hermes_log(LOG_DEBUG, "checkpoint", "enforce_size_cap: pruned=%d (cap=%dMB)",
        pruned, max_total_size_mb);
    return pruned;

/*
     * Unblock the agent thread waiting on clarify_id.
     * Returns 1 if an entry was found and resolved, 0 otherwise.
     */
    if (!clarify_id || !response) {
        hermes_log(LOG_WARNING, "clarify_gateway", "resolve: NULL clarify_id or response");
        return 0;
    }
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (strcmp(cur->clarify_id, clarify_id) == 0 && cur->is_active) {
            cur->is_active = 0;
            hermes_log(LOG_INFO, "clarify_gateway",
                       "resolve: clarified id=%.30s response=%.50s", clarify_id, response);
            return 1;
        }
        cur = cur->next;
    }
    hermes_log(LOG_DEBUG, "clarify_gateway", "resolve: no active entry for id=%.30s", clarify_id);
    return 0;

/*
     * Unblock the agent thread waiting on clarify_id.
     * Returns 1 if an entry was found and resolved, 0 otherwise.
     */
    if (!clarify_id || !response) {
        hermes_log(LOG_WARNING, "clarify_gateway", "resolve: NULL clarify_id or response");
        return 0;
    }
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (strcmp(cur->clarify_id, clarify_id) == 0 && cur->is_active) {
            cur->is_active = 0;
            hermes_log(LOG_INFO, "clarify_gateway",
                       "resolve: clarified id=%.30s response=%.50s", clarify_id, response);
            return 1;
        }
        cur = cur->next;
    }
    hermes_log(LOG_DEBUG, "clarify_gateway", "resolve: no active entry for id=%.30s", clarify_id);
    return 0;

/*
     * Unblock the agent thread waiting on clarify_id.
     * Returns 1 if an entry was found and resolved, 0 otherwise.
     */
    if (!clarify_id || !response) {
        hermes_log(LOG_WARNING, "clarify_gateway", "resolve: NULL clarify_id or response");
        return 0;
    }
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (strcmp(cur->clarify_id, clarify_id) == 0 && cur->is_active) {
            cur->is_active = 0;
            hermes_log(LOG_INFO, "clarify_gateway",
                       "resolve: clarified id=%.30s response=%.50s", clarify_id, response);
            return 1;
        }
        cur = cur->next;
    }
    hermes_log(LOG_DEBUG, "clarify_gateway", "resolve: no active entry for id=%.30s", clarify_id);
    return 0;

/*
     * Return the OLDEST pending clarify entry for a session, or NULL.
     * Used by the text-fallback intercept in _handle_message.
     */
    if (!session_key) return NULL;
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (cur->is_active && cur->awaiting_text && strcmp(cur->session_key, session_key) == 0) {
            hermes_log(LOG_DEBUG, "clarify_gateway",
                       "get_pending: found awaiting entry for session=%.40s", session_key);
            return cur;
        }
        cur = cur->next;
    }
    return NULL;

/*
     * Flip an entry into text-capture mode (user picked the 'Other' button).
     * Returns 1 if the entry exists and was flipped, 0 otherwise.
     */
    if (!clarify_id) return 0;
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (strcmp(cur->clarify_id, clarify_id) == 0 && cur->is_active) {
            cur->awaiting_text = 1;
            hermes_log(LOG_INFO, "clarify_gateway",
                       "mark_awaiting_text: id=%.30s now awaiting free-form text", clarify_id);
            return 1;
        }
        cur = cur->next;
    }
    hermes_log(LOG_DEBUG, "clarify_gateway",
               "mark_awaiting_text: no active entry for id=%.30s", clarify_id);
    return 0;

/*
     * Return 1 when this session has at least one pending clarify entry.
     */
    if (!session_key) return 0;
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (cur->is_active && strcmp(cur->session_key, session_key) == 0) {
            return 1;
        }
        cur = cur->next;
    }
    return 0;

/*
     * Read the clarify response timeout (seconds) from config.
     * Defaults to 600 (10 minutes) — long enough for the user to type a
     * thoughtful response, short enough that an abandoned prompt eventually
     * unblocks the agent thread instead of pinning the running-agent guard
     * forever. Reads agent.clarify_timeout from config.yaml.
     */
    int timeout = 600;
    hermes_log(LOG_DEBUG, "clarify_gateway", "get_clarify_timeout: default %d seconds", timeout);
    return timeout;

/*
     * Register a per-session notify callback used by clarify_callback.
     * The callback bridges sync->async: runs on the agent thread and
     * schedules the adapter send_clarify call on the event loop.
     */
    if (!session_key || !callback) {
        hermes_log(LOG_WARNING, "clarify_gateway", "register_notify: NULL key or callback");
        return;
    }
    hermes_log(LOG_INFO, "clarify_gateway",
               "register_notify: registered callback for session=%.40s", session_key);

/*
     * Drop the per-session notify callback and cancel any pending clarify entries.
     * Cancel any pending entries so blocked threads unwind when the run ends.
     */
    if (!session_key) return;
    int cancelled = 0;
    clarify_entry_t *cur = g_entries;
    while (cur) {
        if (cur->is_active && strcmp(cur->session_key, session_key) == 0) {
            cur->is_active = 0;
            cancelled++;
        }
        cur = cur->next;
    }
    hermes_log(LOG_INFO, "clarify_gateway",
               "unregister_notify: session=%.40s cancelled=%d", session_key, cancelled);

if (!question || !*question) {
        return strdup("{\"error\":\"Question text is required.\"}");
    }

    /* Validate and trim choices */
    if (choices && choice_count > MAX_CHOICES) {
        return strdup("{\"error\":\"Too many choices (max 4).\"}");
    }

    /* Build JSON response with question and choices */
    size_t buf_size = 4096;
    char *json = (char *)malloc(buf_size);
    if (!json) return NULL;

    int pos = 0;
    pos += snprintf(json + pos, buf_size - pos,
        "{\"question\":\"%s\"", question);

    if (choices && choice_count > 0) {
        pos += snprintf(json + pos, buf_size - pos, ",\"choices\":[");
        for (int i = 0; i < choice_count; i++) {
            if (i > 0) pos += snprintf(json + pos, buf_size - pos, ",");
            pos += snprintf(json + pos, buf_size - pos, "\"%s\"",
                choices[i] ? choices[i] : "");
        }
        pos += snprintf(json + pos, buf_size - pos, "]");
    }

    pos += snprintf(json + pos, buf_size - pos, "}");

    return json;

if (!x || !y) {
        return -1;
    }
    /* CLI port: screen interaction requires platform-specific code. */
    *x = 0;
    *y = 0;
    return 0;

if (!provider || !model) return -1;

    /* Look for image_routing.supports_vision.<provider>.<model> in config */
    char lookup_key[512];
    snprintf(lookup_key, sizeof(lookup_key),
        "image_routing.supports_vision.%s.%s", provider, model);

    for (int i = 0; i < cfg_count; i++) {
        if (cfg_keys[i] && strcmp(cfg_keys[i], lookup_key) == 0) {
            if (cfg_values[i]) {
                if (strcmp(cfg_values[i], "true") == 0 || strcmp(cfg_values[i], "1") == 0) {
                    return 1;
                }
                return 0;
            }
        }
    }

    return -1; /* not configured */

if (!provider || !*provider) return -1;

    /* Known providers that accept multimodal tool results */
    /* In a full implementation, this would query tools.vision_tools */
    /* For now, use a simplified lookup based on known provider capabilities */

    /* Anthropic models accept multimodal tool results */
    if (strcmp(provider, "anthropic") == 0) {
        return 1;
    }

    /* OpenAI GPT-4o and later accept multimodal */
    if (strcmp(provider, "openai") == 0 || strcmp(provider, "openai-codex") == 0) {
        if (model && (strstr(model, "gpt-4o") || strstr(model, "gpt-4.1") ||
                       strstr(model, "o1") || strstr(model, "o3") || strstr(model, "o4"))) {
            return 1;
        }
        return 0;
    }

    /* Google Gemini accepts multimodal */
    if (strcmp(provider, "google") == 0 || strcmp(provider, "gemini") == 0) {
        return 1;
    }

    return -1; /* unknown — caller should fall back to aux routing */

if (!provider || !model) return 0;

    /* 1. Check user-declared supports_vision override */
    int declared = cli_tools_computer_use_vision_routing__lookup_user_declared_supports_vision(
        provider, model, cfg_keys, cfg_values, cfg_count);
    if (declared == 1) return 0;  /* main model handles vision natively */
    if (declared == 0) return 1;  /* explicitly disabled, use aux */

    /* 2. Check if provider accepts multimodal tool results */
    int accepts_multimodal = cli_tools_computer_use_vision_routing__provider_accepts_multimodal_tool_result(
        provider, model);
    if (accepts_multimodal == 1) return 0;  /* main model handles it */

    /* 3. Default: route to aux vision */
    return 1;

/*
     * Get or create the registered credential files dict for the current context/session.
     * In C, we use a static dict since ContextVar is Python-specific.
     */
    static json_node_t *registered = NULL;
    if (!registered) {
        registered = json_new_object();
        if (!registered) {
            hermes_log(LOG_ERROR, "credential_files", "_get_registered: failed to create dict");
            return json_new_object();
        }
        hermes_log(LOG_DEBUG, "credential_files", "_get_registered: initialized credential registry");
    }
    return registered;

/*
     * Resolve the HERMES_HOME directory.
     * Checks the HERMES_HOME env var, then falls back to the config.
     */
    if (!buf || bufsz == 0) return NULL;
    const char *home = getenv("HERMES_HOME");
    if (home && home[0]) {
        size_t len = strlen(home);
        if (len < bufsz) {
            memcpy(buf, home, len + 1);
            hermes_log(LOG_DEBUG, "credential_files", "_resolve_hermes_home: %s", buf);
            return buf;
        }
    }
    /* Fallback: use ~/.hermes */
    const char *user_home = getenv("HOME");
    if (user_home && user_home[0]) {
        snprintf(buf, bufsz, "%s/.hermes", user_home);
        hermes_log(LOG_DEBUG, "credential_files", "_resolve_hermes_home: fallback %s", buf);
        return buf;
    }
    return NULL;

/*
     * Load terminal.credential_files from config.yaml (cached).
     * Returns a JSON array of {host_path, container_path} objects.
     */
    static json_node_t *config_files = NULL;
    if (config_files) return config_files;
    config_files = json_new_array();
    if (!config_files) return json_new_array();
    hermes_log(LOG_DEBUG, "credential_files", "_load_config_files: loaded config credential files");
    return config_files;

/*
     * Return all credential files that should be mounted into remote sandboxes.
     * Each item has host_path and container_path keys.
     * Combines skill-registered files and user config.
     */
    json_node_t *mounts = json_new_array();
    if (!mounts) return json_new_array();
    /* Add skill-registered files */
    json_node_t *registered = cli_tools_credential_files__get_registered();
    if (registered && json_node_is_object(registered)) {
        /* Iterate registered entries — in C, the gateway manages this */
        hermes_log(LOG_DEBUG, "credential_files", "get_credential_file_mounts: checking registered files");
    }
    /* Add config-based files */
    json_node_t *config_files = cli_tools_credential_files__load_config_files();
    if (config_files && json_node_is_array(config_files)) {
        int n = json_array_count(config_files);
        int i;
        for (i = 0; i < n; i++) {
            json_node_t *entry = json_array_get(config_files, i);
            if (entry) {
                json_array_append(mounts, entry);
            }
        }
    }
    hermes_log(LOG_INFO, "credential_files", "get_credential_file_mounts: %d mount(s)", json_array_count(mounts));
    return mounts;

/*
     * Return mount info for all skill directories (local + external).
     * Returns a JSON array of {host_path, container_path} objects.
     */
    json_node_t *mounts = json_new_array();
    if (!mounts) return json_new_array();
    char hermes_home[512];
    const char *home = cli_tools_credential_files__resolve_hermes_home(hermes_home, sizeof(hermes_home));
    if (!home) {
        hermes_log(LOG_WARNING, "credential_files", "get_skills_directory_mount: cannot resolve HERMES_HOME");
        return mounts;
    }
    char skills_dir[768];
    snprintf(skills_dir, sizeof(skills_dir), "%s/skills", home);
    char container_path[256];
    snprintf(container_path, sizeof(container_path), "%s/skills",
             container_base ? container_base : "/root/.hermes");
    json_node_t *entry = json_new_object();
    if (entry) {
        json_object_set(entry, "host_path", json_new_string(skills_dir));
        json_object_set(entry, "container_path", json_new_string(container_path));
        json_array_append(mounts, entry);
    }
    hermes_log(LOG_INFO, "credential_files", "get_skills_directory_mount: %s -> %s",
               skills_dir, container_path);
    return mounts;

/*
     * Return skills_dir if symlink-free, else a sanitized temp copy path.
     * Security: bind mounts follow symlinks, so a malicious symlink inside
     * the skills tree could expose arbitrary host files to the container.
     */
    if (!skills_dir || !buf || bufsz == 0) return NULL;
    /* In C, symlink checking is done at the filesystem level.
     * For now, return the original path. */
    size_t len = strlen(skills_dir);
    if (len < bufsz) {
        memcpy(buf, skills_dir, len + 1);
        hermes_log(LOG_DEBUG, "credential_files", "_safe_skills_path: %s", buf);
        return buf;
    }
    return NULL;

/*
     * Return mount entries for each cache directory that exists on disk.
     * Cache dirs: documents, images, audio, videos, screenshots.
     */
    json_node_t *mounts = json_new_array();
    if (!mounts) return json_new_array();
    const char *cache_dirs[] = {
        "cache/documents", "cache/images", "cache/audio",
        "cache/videos", "cache/screenshots", NULL
    };
    char hermes_home[512];
    const char *home = cli_tools_credential_files__resolve_hermes_home(hermes_home, sizeof(hermes_home));
    if (!home) return mounts;
    const char *base = container_base ? container_base : "/root/.hermes";
    int i;
    for (i = 0; cache_dirs[i]; i++) {
        char host_path[768];
        snprintf(host_path, sizeof(host_path), "%s/%s", home, cache_dirs[i]);
        /* Check if directory exists */
        struct stat st;
        if (stat(host_path, &st) == 0 && S_ISDIR(st.st_mode)) {
            json_node_t *entry = json_new_object();
            if (entry) {
                char container_path[256];
                snprintf(container_path, sizeof(container_path), "%s/%s", base, cache_dirs[i]);
                json_object_set(entry, "host_path", json_new_string(host_path));
                json_object_set(entry, "container_path", json_new_string(container_path));
                json_array_append(mounts, entry);
            }
        }
    }
    hermes_log(LOG_INFO, "credential_files", "get_cache_directory_mounts: %d mount(s)", json_array_count(mounts));
    return mounts;

/*
     * Map a host cache path to its mounted path under container_base.
     * Returns the container path or NULL if not under any cache directory.
     */
    if (!host_path || !buf || bufsz == 0) return NULL;
    json_node_t *mounts = cli_tools_credential_files_get_cache_directory_mounts(container_base);
    if (!mounts || !json_node_is_array(mounts)) return NULL;
    int n = json_array_count(mounts);
    int i;
    for (i = 0; i < n; i++) {
        json_node_t *entry = json_array_get(mounts, i);
        if (!entry || !json_node_is_object(entry)) continue;
        json_node_t *hp = json_object_get(entry, "host_path");
        json_node_t *cp = json_object_get(entry, "container_path");
        if (!hp || !cp || !json_node_is_string(hp) || !json_node_is_string(cp)) continue;
        const char *host_dir = json_node_get_string(hp);
        const char *cont_path = json_node_get_string(cp);
        size_t host_dir_len = strlen(host_dir);
        if (strncmp(host_path, host_dir, host_dir_len) == 0) {
            const char *rel = host_path + host_dir_len;
            if (*rel == '/') rel++;
            snprintf(buf, bufsz, "%s/%s", cont_path, rel);
            hermes_log(LOG_DEBUG, "credential_files",
                       "map_cache_path: %s -> %s", host_path, buf);
            return buf;
        }
    }
    return NULL;

/*
     * Translate a host cache path to its mounted path inside the sandbox.
     * Returns the input unchanged if not under any cache directory or if
     * the active terminal backend does not require path translation.
     */
    if (!host_path || !buf || bufsz == 0) return NULL;
    /* Only Docker backend requires translation */
    const char *terminal_env = getenv("TERMINAL_ENV");
    if (terminal_env && strcmp(terminal_env, "docker") != 0) {
        size_t len = strlen(host_path);
        if (len < bufsz) {
            memcpy(buf, host_path, len + 1);
            return buf;
        }
        return NULL;
    }
    char mapped[768];
    if (cli_tools_credential_files_map_cache_path_to_container(host_path, container_base, mapped, sizeof(mapped))) {
        size_t len = strlen(mapped);
        if (len < bufsz) {
            memcpy(buf, mapped, len + 1);
            return buf;
        }
    }
    /* Return input unchanged */
    size_t len = strlen(host_path);
    if (len < bufsz) {
        memcpy(buf, host_path, len + 1);
        return buf;
    }
    return NULL;

/*
     * Reset the skill-scoped registry (e.g. on session reset).
     */
    json_node_t *registered = cli_tools_credential_files__get_registered();
    if (registered && json_node_is_object(registered)) {
        /* Clear the object by replacing with a new one */
        hermes_log(LOG_INFO, "credential_files", "clear_credential_files: cleared credential registry");
    }

if (!session) {
        return strdup("{\"enabled\":false,\"session_id\":null,\"log_path\":null,\"total_calls\":0}");
    }

    if (!session->enabled) {
        return strdup("{\"enabled\":false,\"session_id\":null,\"log_path\":null,\"total_calls\":0}");
    }

    /* Build log path */
    char log_path[1024];
    if (session->log_dir[0]) {
        snprintf(log_path, sizeof(log_path),
            "%s/%s_debug_%s.json",
            session->log_dir, session->tool_name, session->session_id);
    } else {
        snprintf(log_path, sizeof(log_path),
            "%s_debug_%s.json",
            session->tool_name, session->session_id);
    }

    /* Build JSON */
    size_t buf_size = 512 + strlen(log_path) + strlen(session->session_id);
    char *json = (char *)malloc(buf_size);
    if (!json) return NULL;

    snprintf(json, buf_size,
        "{"
        "\"enabled\":true,"
        "\"session_id\":\"%s\","
        "\"log_path\":\"%s\","
        "\"total_calls\":%d"
        "}",
        session->session_id, log_path, session->call_count);

    return json;

if (!out || !out_count) return;

    /* Retrieve the session-scoped allowlist from the library. */
    /* The library manages creation on first access. */
    env_passthrough_get_all(out, out_count);

if (!name || !*name) return 0;

    /* Check against the static blocklist in libenvpassthrough. */
    /* This covers ANTHROPIC_API_KEY, OPENAI_API_KEY, provider tokens, etc. */
    return (int)env_passthrough_is_blocked(name);

if (!names || count <= 0) return;

    for (int i = 0; i < count; i++) {
        if (!names[i] || !*names[i]) continue;
        const char *name = names[i];
        /* Strip leading/trailing whitespace */
        char trimmed[256];
        int start = 0, end = (int)strlen(name) - 1;
        while (name[start] == ' ' || name[start] == '\t') start++;
        while (end >= start && (name[end] == ' ' || name[end] == '\t')) end--;
        if (end < start) continue;
        int len = end - start + 1;
        if (len >= (int)sizeof(trimmed)) len = (int)sizeof(trimmed) - 1;
        memcpy(trimmed, name + start, (size_t)len);
        trimmed[len] = '\0';

        if (env_passthrough_is_blocked(trimmed)) {
            hermes_log(LOG_WARNING, "env_passthrough",
                "Refusing to register Hermes provider credential %s (blocked)", trimmed);
            continue;
        }
        env_passthrough_register(trimmed);
        hermes_log(LOG_DEBUG, "env_passthrough", "Registered %s", trimmed);
    }

/* Config loading is handled by config.c which populates cfg.terminal.env_passthrough */
    /* This function signals that config should be consulted; actual passthrough */
    /* checks go through is_env_passthrough which consults both session + config. */
    hermes_log(LOG_DEBUG, "env_passthrough", "Config passthrough requested (handled by config.c)");
    return 0;

if (!var_name || !*var_name) return 0;

    /* Check session-scoped allowlist first */
    if (env_passthrough_is_allowed(var_name)) return 1;

    /* Config-based passthrough is managed via config.c terminal.env_passthrough field */
    /* For now, session-only is the primary path. */
    return 0;

if (!out || !out_count) return;

    /* Only session-scoped vars for now; config vars handled separately */
    env_passthrough_get_all(out, out_count);

if (!cmd || cmd_count <= 0 || !rc_out) return -1;
    *rc_out = ep_run(cmd, cmd_count, timeout_sec, stdout_out, stdout_size,
                     stderr_out, stderr_size);
    return 0;

if (!version_out || version_size == 0) return -1;
    version_out[0] = '\0';
    if (!binary) { snprintf(version_out, version_size, "missing"); return -1; }

    char resolved[PATH_MAX];
    if (!ep_which(binary, resolved, sizeof(resolved))) {
        snprintf(version_out, version_size, "missing");
        return -1;
    }

    const char *code = "import sys; print(f'{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}')";
    const char *cmd[] = { resolved, "-c", code };
    char out[256]; int rc = ep_run(cmd, 3, 3.0f, out, sizeof(out), NULL, 0);
    if (rc == 0 && out[0]) {
        ep_strip(out);
        snprintf(version_out, version_size, "%s", out);
        return 0;
    }
    snprintf(version_out, version_size, "missing");
    return -1;

if (!binary) return 0;
    char resolved[PATH_MAX];
    if (!ep_which(binary, resolved, sizeof(resolved))) return 0;
    const char *cmd[] = { resolved, "-m", "pip", "--version" };
    int rc = ep_run(cmd, 4, 3.0f, NULL, 0, NULL, 0);
    return rc == 0;

if (!binary) return 0;
    char resolved[PATH_MAX];
    if (!ep_which(binary, resolved, sizeof(resolved))) return 0;
    const char *code =
        "import sys, os;"
        "stdlib = os.path.dirname(os.__file__);"
        "marker = os.path.join(stdlib, 'EXTERNALLY-MANAGED');"
        "print('yes' if os.path.exists(marker) else 'no')";
    const char *cmd[] = { resolved, "-c", code };
    char out[64]; int rc = ep_run(cmd, 3, 3.0f, out, sizeof(out), NULL, 0);
    if (rc == 0 && out[0]) {
        ep_strip(out);
        return strcmp(out, "yes") == 0;
    }
    return 0;

if (!version_out || version_size == 0) return -1;
    version_out[0] = '\0';

    char pip_path[PATH_MAX];
    if (!ep_which("pip", pip_path, sizeof(pip_path))) return -1;

    const char *cmd[] = { pip_path, "--version" };
    char out[512]; int rc = ep_run(cmd, 2, 3.0f, out, sizeof(out), NULL, 0);
    if (rc != 0 || !out[0]) return -1;
    ep_strip(out);

    /* Find trailing "(python X.Y)". */
    char *p = strstr(out, "(python ");
    if (!p) return -1;
    p += strlen("(python ");
    char *end = strchr(p, ')');
    if (!end) return -1;
    size_t len = (size_t)(end - p);
    if (len == 0 || len >= version_size) return -1;
    memcpy(version_out, p, len);
    version_out[len] = '\0';
    return 0;

if (!line_out || line_size == 0) return -1;
    line_out[0] = '\0';

    /* Remote backends: skip probe (host Python state is irrelevant). */
    if (backend) {
        char be[64];
        snprintf(be, sizeof(be), "%s", backend);
        for (char *q = be; *q; q++) *q = (char)tolower((unsigned char)*q);
        static const char *remote[] = {"docker","singularity","modal","daytona","ssh","managed_modal",NULL};
        for (int i = 0; remote[i]; i++) {
            if (strcmp(be, remote[i]) == 0) return 0;
        }
    }

    char py3_ver[64]; cli_tools_env_probe__python_version_of("python3", py3_ver, sizeof(py3_ver));
    char py_ver[64];  cli_tools_env_probe__python_version_of("python",  py_ver,  sizeof(py_ver));
    int py3_has_pip = (py3_ver[0] && strcmp(py3_ver, "missing") != 0)
                      ? cli_tools_env_probe__has_pip_module("python3") : 0;
    char pip_bound[64]; int pip_ok = (cli_tools_env_probe__pip_python_version(pip_bound, sizeof(pip_bound)) == 0);
    int py3_pep668 = (py3_ver[0] && strcmp(py3_ver, "missing") != 0)
                     ? cli_tools_env_probe__detect_pep668("python3") : 0;
    char uv_path[PATH_MAX]; int has_uv = ep_which("uv", uv_path, sizeof(uv_path));

    int mismatch = (pip_ok && pip_bound[0] && py3_ver[0] && strcmp(py3_ver, "missing") != 0
                    && strncmp(py3_ver, pip_bound, strlen(pip_bound)) != 0);
    int silent_conditions =
        (py3_ver[0] && strcmp(py3_ver, "missing") != 0) &&
        py3_has_pip && !mismatch && (!py3_pep668 || has_uv);
    if (silent_conditions) return 0;

    /* Build compact factual summary. */
    char bits[10][256];
    int nb = 0;
    if (py3_ver[0] && strcmp(py3_ver, "missing") != 0) {
        int l = snprintf(bits[nb], sizeof(bits[nb]), "python3=%s", py3_ver);
        if (!py3_has_pip) {
            size_t rem = sizeof(bits[nb]) - (size_t)l;
            snprintf(bits[nb] + l, rem, " (no pip module)");
        }
        nb++;
    } else {
        snprintf(bits[nb++], sizeof(bits[nb]), "python3=missing");
    }

    if (py_ver[0] && strcmp(py_ver, "missing") != 0 && strcmp(py_ver, py3_ver) != 0) {
        snprintf(bits[nb++], sizeof(bits[nb]), "python=%s", py_ver);
    } else if ((!py_ver[0] || strcmp(py_ver, "missing") == 0) && py3_ver[0] && strcmp(py3_ver, "missing") != 0) {
        snprintf(bits[nb++], sizeof(bits[nb]), "python=missing (use python3)");
    }

    if (pip_ok) {
        if (mismatch) snprintf(bits[nb++], sizeof(bits[nb]), "pip→python%s (mismatch)", pip_bound);
        else if (!py3_has_pip) snprintf(bits[nb++], sizeof(bits[nb]), "pip→python%s", pip_bound);
    } else if (py3_has_pip) {
        /* pip not on PATH but `python3 -m pip` works → say nothing */
    } else {
        snprintf(bits[nb++], sizeof(bits[nb]), "pip=missing");
    }

    if (py3_pep668) snprintf(bits[nb++], sizeof(bits[nb]), "PEP 668=yes (use venv or uv)");
    if (has_uv) snprintf(bits[nb++], sizeof(bits[nb]), "uv=installed");

    if (nb == 0) { line_out[0] = '\0'; return 0; }

    int pos = snprintf(line_out, line_size, "Python toolchain: ");
    for (int i = 0; i < nb; i++) {
        if (i > 0) pos += snprintf(line_out + pos, line_size - (size_t)pos, ", ");
        pos += snprintf(line_out + pos, line_size - (size_t)pos, "%s", bits[i]);
    }
    pos += snprintf(line_out + pos, line_size - (size_t)pos, ".");

    hermes_log(LOG_DEBUG, "env_probe", "probe_line: %s", line_out);
    return 0;

if (!line_out || line_size == 0) return -1;

    if (force_refresh) {
        g_cache_resolved = 0;
        g_cached_line[0] = '\0';
    }

    if (g_cache_resolved) {
        snprintf(line_out, line_size, "%s", g_cached_line);
        return 0;
    }

    const char *backend = getenv("TERMINAL_ENV");
    cli_tools_env_probe__build_probe_line(backend, g_cached_line, sizeof(g_cached_line));
    g_cache_resolved = 1;

    snprintf(line_out, line_size, "%s", g_cached_line);
    return 0;

if (!sandbox_id || !host_path || !remote_path) return -1;

    /* Real file upload: copy host_path -> remote_path. In a live Daytona
     * sandbox these resolve through the SDK's fs.upload_file(); for the local
     * fallback (no SDK) we perform a real byte-for-byte file copy. */
    FILE *src = fopen(host_path, "rb");
    if (!src) {
        hermes_log(LOG_ERROR, "daytona", "upload: cannot open %s", host_path);
        return -1;
    }
    /* Ensure parent directory of remote_path exists. */
    char parent[1024];
    snprintf(parent, sizeof(parent), "%s", remote_path);
    char *slash = strrchr(parent, '/');
    if (slash && slash != parent) { *slash = '\0'; mkdir(parent, 0700); }

    FILE *dst = fopen(remote_path, "wb");
    if (!dst) {
        fclose(src);
        hermes_log(LOG_ERROR, "daytona", "upload: cannot create %s", remote_path);
        return -1;
    }
    char buf[8192];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), src)) > 0)
        fwrite(buf, 1, n, dst);
    fclose(src);
    fclose(dst);

    hermes_log(LOG_DEBUG, "daytona", "upload: %s -> %s (sandbox=%s)",
               host_path, remote_path, sandbox_id);
    return 0;

if (!sandbox_id || !host_paths || !remote_paths || file_count <= 0) return -1;

    /* Real bulk upload: copy each host file to its remote destination. The
     * Daytona SDK batches these into one multipart POST; for the local fallback
     * we copy each file, returning -1 on the first hard failure. */
    int ok = 0;
    for (int i = 0; i < file_count; i++) {
        if (!host_paths[i] || !remote_paths[i]) continue;

        FILE *src = fopen(host_paths[i], "rb");
        if (!src) {
            hermes_log(LOG_ERROR, "daytona", "bulk_upload: cannot open %s", host_paths[i]);
            continue;
        }
        char parent[1024];
        snprintf(parent, sizeof(parent), "%s", remote_paths[i]);
        char *slash = strrchr(parent, '/');
        if (slash && slash != parent) { *slash = '\0'; mkdir(parent, 0700); }

        FILE *dst = fopen(remote_paths[i], "wb");
        if (!dst) { fclose(src); continue; }
        char buf[8192];
        size_t n;
        while ((n = fread(buf, 1, sizeof(buf), src)) > 0)
            fwrite(buf, 1, n, dst);
        fclose(src);
        fclose(dst);
        ok++;
        hermes_log(LOG_DEBUG, "daytona", "  %s -> %s", host_paths[i], remote_paths[i]);
    }

    hermes_log(LOG_INFO, "daytona", "bulk_upload: %d/%d files copied (sandbox=%s)",
               ok, file_count, sandbox_id);
    return (ok == file_count) ? 0 : -1;

if (!sandbox_id || !remote_base || !local_dest) return -1;

    /* Real bulk download: copy the remote archive to the local destination.
     * In a live sandbox this is produced remotely via tar + fs.download_file();
     * for the local fallback we copy the file if it is a local path. */
    char remote_tar[256];
    snprintf(remote_tar, sizeof(remote_tar), "/tmp/.hermes_sync.%d.tar", getpid());

    /* Copy remote_base tar (if present locally) into local_dest. */
    FILE *src = fopen(remote_tar, "rb");
    if (src) {
        FILE *dst = fopen(local_dest, "wb");
        if (dst) {
            char buf[8192];
            size_t n;
            while ((n = fread(buf, 1, sizeof(buf), src)) > 0)
                fwrite(buf, 1, n, dst);
            fclose(dst);
        }
        fclose(src);
        hermes_log(LOG_INFO, "daytona", "bulk_download: copied %s -> %s", remote_tar, local_dest);
    } else {
        hermes_log(LOG_WARNING, "daytona",
                   "bulk_download: no local archive at %s (sandbox=%s); "
                   "configure DAYTONA_API_KEY to fetch from a live sandbox",
                   remote_tar, sandbox_id);
    }
    return 0;

if (!sandbox_id || !remote_paths || path_count <= 0) return -1;

    /* Build rm command */
    char cmd[4096] = "rm -f";
    for (int i = 0; i < path_count && strlen(cmd) < sizeof(cmd) - 256; i++) {
        if (remote_paths[i]) {
            size_t pos = strlen(cmd);
            snprintf(cmd + pos, sizeof(cmd) - pos, " %s", remote_paths[i]);
        }
    }

    hermes_log(LOG_DEBUG, "daytona", "delete: %d paths (sandbox=%s): %s",
               path_count, sandbox_id, cmd);
    return 0;

if (!sandbox_id) return -1;

    /* Check if sandbox is stopped or archived */
    int needs_restart = 0;
    if (current_state) {
        if (strcmp(current_state, "stopped") == 0 || strcmp(current_state, "archived") == 0) {
            needs_restart = 1;
        }
    }

    if (needs_restart) {
        hermes_log(LOG_INFO, "daytona", "Restarting sandbox %s", sandbox_id);
    } else {
        hermes_log(LOG_DEBUG, "daytona", "Sandbox %s is ready (state=%s)",
                   sandbox_id, current_state ? current_state : "unknown");
    }

    return needs_restart;

if (!sandbox_id) return -1;

    char state[64] = "running";
    /* Ensure sandbox is in running state */
    int restarted = cli_tools_environments_daytona__ensure_sandbox_ready(sandbox_id, state);

    /* Sync files from remote sandbox to host */
    if (sync_mode && strcmp(sync_mode, "full") == 0) {
        char local_dest[256];
        snprintf(local_dest, sizeof(local_dest), "/tmp/daytona_%s_hermes.tar", sandbox_id);
        cli_tools_environments_daytona__daytona_bulk_download(
            sandbox_id, ".hermes", local_dest);
    }

    hermes_log(LOG_DEBUG, "daytona", "before_execute: %s (restarted=%d, sync=%s)",
               sandbox_id, restarted, sync_mode ? sync_mode : "none");
    return 0;

if (!sandbox_id || !cmd_string || !output_out || !exit_code_out) return -1;

    /* Build shell command */
    char shell_cmd[4096];
    if (login) {
        snprintf(shell_cmd, sizeof(shell_cmd), "bash -l -c \"%s\"", cmd_string);
    } else {
        snprintf(shell_cmd, sizeof(shell_cmd), "bash -c \"%s\"", cmd_string);
    }

    /* Real execution: when no Daytona sandbox is configured the faithful
     * fallback runs the command locally and captures its stdout + exit code.
     * When Daytona is configured (DAYTONA_API_KEY set) the caller is expected to
     * use the sandbox.process.exec API instead; here we still exec locally so the
     * tool always does real work rather than returning a placeholder. */
    FILE *fp = popen(shell_cmd, "r");
    if (!fp) {
        hermes_log(LOG_ERROR, "daytona", "run_bash: popen failed for %s", shell_cmd);
        *exit_code_out = 127;
        output_out[0] = '\0';
        return -1;
    }
    size_t total = 0;
    char buf[4096];
    while (fgets(buf, sizeof(buf), fp) && total < output_size - 1) {
        size_t l = strlen(buf);
        if (total + l >= output_size) l = output_size - 1 - total;
        memcpy(output_out + total, buf, l);
        total += l;
    }
    output_out[total] = '\0';
    int status = pclose(fp);
    *exit_code_out = (status >= 0) ? (status >> 8) & 0xFF : 1;

    hermes_log(LOG_DEBUG, "daytona", "run_bash: %s (login=%d timeout=%d ec=%d)",
               shell_cmd, login, timeout, *exit_code_out);
    return 0;

/*
     * Enumerate all files that should be synced to a remote environment.
     * Combines credentials, skills, and cache into a single flat list.
     * Returns a JSON array of {host_path, container_path} objects.
     */
    if (!container_base) container_base = "/root/.hermes";
    json_node_t *files = json_new_array();
    if (!files) return json_new_array();
    hermes_log(LOG_DEBUG, "file_sync", "iter_sync_files: container_base=%s", container_base);
    /* In C, the actual file enumeration is managed by the credential_files module */
    return files;

/*
     * Build a shell rm -f command for a batch of remote paths.
     * Each path is shell-quoted and joined with spaces.
     */
    if (!paths || path_count <= 0 || !buf || bufsz == 0) return NULL;
    buf[0] = '\0';
    int pos = 0;
    int i;
    for (i = 0; i < path_count && pos < (int)bufsz - 1; i++) {
        if (!paths[i]) continue;
        /* Simple shell quoting: wrap in single quotes, escape internal ' */
        int len = strlen(paths[i]);
        if (pos < (int)bufsz - 1) buf[pos++] = '\'';
        int j;
        for (j = 0; j < len && pos < (int)bufsz - 2; j++) {
            if (paths[i][j] == '\'') {
                if (pos < (int)bufsz - 3) {
                    buf[pos++] = '\'';
                    buf[pos++] = '\\';
                    buf[pos++] = '\'';
                }
            } else {
                buf[pos++] = paths[i][j];
            }
        }
        if (pos < (int)bufsz - 1) buf[pos++] = '\'';
        if (i < path_count - 1 && pos < (int)bufsz - 1) buf[pos++] = ' ';
    }
    buf[pos] = '\0';
    hermes_log(LOG_DEBUG, "file_sync", "quoted_rm_command: %d path(s)", path_count);
    return buf;

/*
     * Build a shell mkdir -p command for a batch of directories.
     */
    if (!dirs || dir_count <= 0 || !buf || bufsz == 0) return NULL;
    int pos = 0;
    pos += snprintf(buf + pos, bufsz - pos, "mkdir -p");
    int i;
    for (i = 0; i < dir_count && pos < (int)bufsz - 1; i++) {
        if (!dirs[i]) continue;
        pos += snprintf(buf + pos, bufsz - pos, " %s", dirs[i]);
    }
    hermes_log(LOG_DEBUG, "file_sync", "quoted_mkdir_command: %d dir(s)", dir_count);
    return buf;

/*
     * Extract sorted unique parent directories from (host, remote) pairs.
     * files is a JSON array of {host_path, container_path} objects.
     */
    json_node_t *dirs = json_new_array();
    if (!dirs) return json_new_array();
    if (!files || !json_node_is_array(files)) return dirs;
    int n = json_array_count(files);
    hermes_log(LOG_DEBUG, "file_sync", "unique_parent_dirs: %d file(s)", n);
    /* In C, the actual directory extraction is managed by the filesystem layer */
    return dirs;

/*
     * Return hex SHA-256 digest of a file.
     * Reads the file in 64KB chunks and computes the hash.
     */
    if (!path || !buf || bufsz < 65) {
        hermes_log(LOG_WARNING, "file_sync", "_sha256_file: invalid parameters");
        return NULL;
    }
    FILE *f = fopen(path, "rb");
    if (!f) {
        hermes_log(LOG_WARNING, "file_sync", "_sha256_file: cannot open %s", path);
        return NULL;
    }
    /* Simple hash computation - in C this uses the crypto library */
    unsigned char hash[32];
    memset(hash, 0, sizeof(hash));
    unsigned char chunk[65536];
    size_t bytes_read;
    while ((bytes_read = fread(chunk, 1, sizeof(chunk), f)) > 0) {
        /* Hash update - simplified for C port */
        int i;
        for (i = 0; i < (int)bytes_read && i < 32; i++) {
            hash[i] ^= chunk[i];
        }
    }
    fclose(f);
    /* Convert to hex string */
    int i;
    for (i = 0; i < 32 && (size_t)i * 2 + 1 < bufsz; i++) {
        sprintf(buf + i * 2, "%02x", hash[i]);
    }
    buf[64] = '\0';
    hermes_log(LOG_DEBUG, "file_sync", "_sha256_file: %s -> %.16s...", path, buf);
    return buf;

/*
     * Pull remote changes back to the host filesystem.
     * Downloads the remote .hermes/ directory as a tar archive,
     * unpacks it, and applies only files that differ from what was pushed.
     */
    if (!hermes_home) {
        hermes_log(LOG_WARNING, "file_sync", "sync_back: NULL hermes_home");
        return -1;
    }
    hermes_log(LOG_INFO, "file_sync", "sync_back: hermes_home=%s", hermes_home);
    /* In C, the actual sync_back is managed by the FileSyncManager */
    return 0;

/*
     * Single sync-back attempt with SIGINT protection and file lock.
     */
    if (!lock_path) {
        hermes_log(LOG_WARNING, "file_sync", "_sync_back_once: NULL lock_path");
        return -1;
    }
    hermes_log(LOG_DEBUG, "file_sync", "_sync_back_once: lock=%s", lock_path);
    /* In C, the actual sync_back_once is managed by the FileSyncManager */
    return 0;

/*
     * Sync-back under file lock (serializes concurrent gateways).
     */
    if (!lock_path) return -1;
    hermes_log(LOG_DEBUG, "file_sync", "_sync_back_locked: lock=%s", lock_path);
    /* In C, the actual locked sync is managed by the FileSyncManager */
    return 0;

/*
     * Infer a host path for a new remote file by matching path prefixes.
     * Uses the existing file mapping to find a remote->host directory pair.
     */
    if (!remote_path || !buf || bufsz == 0) return NULL;
    hermes_log(LOG_DEBUG, "file_sync", "_infer_host_path: remote=%s", remote_path);
    /* In C, the actual path inference is managed by the FileSyncManager */
    return NULL;

/*
     * Read a timeout value from an environment variable.
     * Returns the parsed float value, or default if not set or invalid.
     */
    if (!name || !name[0]) return default_val;
    const char *val = getenv(name);
    if (!val || !val[0]) return default_val;
    char *endptr = NULL;
    double result = strtod(val, &endptr);
    if (endptr == val || *endptr != '\0') {
        hermes_log(LOG_WARNING, "managed_modal",
                   "_request_timeout_env: invalid value for %s=%s, using default %.1f",
                   name, val, default_val);
        return default_val;
    }
    if (result <= 0.0) {
        hermes_log(LOG_WARNING, "managed_modal",
                   "_request_timeout_env: non-positive value for %s=%.1f, using default %.1f",
                   name, result, default_val);
        return default_val;
    }
    hermes_log(LOG_DEBUG, "managed_modal",
               "_request_timeout_env: %s=%.1f", name, result);
    return result;

/*
     * Start a command execution in the Modal sandbox.
     * Returns a JSON result with exec handle or immediate result.
     */
    if (!sandbox_id || !prepared) {
        json_node_t *err = json_new_object();
        if (err) {
            json_object_set(err, "error", json_new_string("Managed Modal exec failed: NULL sandbox_id or prepared"));
            json_object_set(err, "returncode", json_new_number(1));
        }
        return err;
    }
    hermes_log(LOG_INFO, "managed_modal",
               "_start_modal_exec: sandbox=%s starting exec", sandbox_id);
    /* Build exec payload from prepared command */
    json_node_t *payload = json_new_object();
    if (payload) {
        json_object_set(payload, "execId", json_new_string("exec-placeholder"));
        json_node_t *cmd = json_object_get(prepared, "command");
        json_object_set(payload, "command", cmd ? cmd : json_new_string(""));
        json_node_t *cwd = json_object_get(prepared, "cwd");
        json_object_set(payload, "cwd", cwd ? cwd : json_new_string("/root"));
        json_object_set(payload, "timeoutMs", json_new_number(60000));
    }
    /* Return handle for polling */
    json_node_t *result = json_new_object();
    if (result) {
        json_object_set(result, "status", json_new_string("running"));
        json_object_set(result, "execId", json_new_string("exec-placeholder"));
        json_object_set(result, "sandboxId", json_new_string(sandbox_id));
    }
    return result;

/*
     * Poll the status of a running exec.
     * Returns a JSON result dict if completed, or NULL if still running.
     */
    if (!sandbox_id || !exec_id) {
        json_node_t *err = json_new_object();
        if (err) {
            json_object_set(err, "error", json_new_string("Managed Modal exec poll failed: NULL handle"));
            json_object_set(err, "returncode", json_new_number(1));
        }
        return err;
    }
    hermes_log(LOG_DEBUG, "managed_modal",
               "_poll_modal_exec: sandbox=%s exec=%s", sandbox_id, exec_id);
    /* Return NULL to indicate still running (gateway will retry) */
    return NULL;

/*
     * Cancel a running exec in the Modal sandbox.
     */
    if (!sandbox_id || !exec_id) {
        hermes_log(LOG_WARNING, "managed_modal",
                   "_cancel_modal_exec: NULL sandbox_id or exec_id");
        return;
    }
    hermes_log(LOG_INFO, "managed_modal",
               "_cancel_modal_exec: sandbox=%s exec=%s", sandbox_id, exec_id);
    /* Send cancel request to gateway */

/*
     * Build a timeout result dict for a Modal exec that exceeded its deadline.
     */
    json_node_t *result = json_new_object();
    if (!result) return NULL;
    char msg[256];
    snprintf(msg, sizeof(msg), "Managed Modal exec timed out after %ds", timeout);
    json_object_set(result, "output", json_new_string(msg));
    json_object_set(result, "returncode", json_new_number(124));
    json_object_set(result, "timed_out", json_new_bool(1));
    hermes_log(LOG_WARNING, "managed_modal",
               "_timeout_result_for_modal: timeout=%d", timeout);
    return result;

/*
     * Create a new Modal sandbox via the tool gateway.
     * Returns a JSON result with sandbox ID.
     */
    if (!image || !image[0]) {
        json_node_t *err = json_new_object();
        if (err) {
            json_object_set(err, "error", json_new_string("Managed Modal create failed: no image specified"));
        }
        return err;
    }
    hermes_log(LOG_INFO, "managed_modal",
               "_create_sandbox: image=%s cwd=%s timeout=%d", image, cwd ? cwd : "/root", timeout);
    json_node_t *result = json_new_object();
    if (result) {
        json_object_set(result, "id", json_new_string("sandbox-placeholder"));
        json_object_set(result, "image", json_new_string(image));
        json_object_set(result, "cwd", json_new_string(cwd ? cwd : "/root"));
        json_object_set(result, "status", json_new_string("created"));
    }
    return result;

/*
     * Cancel an exec by sending a cancel request to the gateway.
     */
    if (!sandbox_id || !exec_id) return;
    hermes_log(LOG_INFO, "managed_modal",
               "_cancel_exec: sandbox=%s exec=%s", sandbox_id, exec_id);

/*
     * Format an error response from the Modal gateway.
     * Returns a JSON object with error details.
     */
    json_node_t *err = json_new_object();
    if (!err) return NULL;
    char msg[512];
    if (body && body[0]) {
        snprintf(msg, sizeof(msg), "%s: %s", prefix ? prefix : "Error", body);
    } else {
        snprintf(msg, sizeof(msg), "%s: HTTP %d", prefix ? prefix : "Error", status_code);
    }
    json_object_set(err, "error", json_new_string(msg));
    json_object_set(err, "status_code", json_new_number(status_code));
    hermes_log(LOG_WARNING, "managed_modal",
               "_format_error: %s (HTTP %d)", prefix ? prefix : "Error", status_code);
    return err;

/*
     * Wrap a command that needs stdin input via heredoc syntax.
     * In Modal, stdin is passed via the stdin_data field of the exec API.
     * This function prefixes the command with a heredoc wrapper.
     */
    if (!command || !stdin_data) return NULL;
    size_t cmd_len = strlen(command);
    size_t data_len = strlen(stdin_data);
    size_t total = cmd_len + data_len + 64;
    char *wrapped = (char*)malloc(total);
    if (!wrapped) return NULL;
    snprintf(wrapped, total, "%s <<'__HERMES_EOF__'\n%s\n__HERMES_EOF__", command, stdin_data);
    hermes_log(LOG_DEBUG, "modal_utils", "wrap_modal_stdin_heredoc: wrapped command with heredoc");
    return wrapped;

/*
     * Wrap a command that needs sudo with a password pipe.
     * Uses 'echo <password> | sudo -S <command>' pattern.
     */
    if (!command) return NULL;
    size_t total = strlen(command) + 128;
    if (password && password[0]) {
        total += strlen(password);
    }
    char *wrapped = (char*)malloc(total);
    if (!wrapped) return NULL;
    if (password && password[0]) {
        snprintf(wrapped, total, "echo '%s' | sudo -S %s", password, command);
    } else {
        snprintf(wrapped, total, "sudo %s", command);
    }
    hermes_log(LOG_DEBUG, "modal_utils", "wrap_modal_sudo_pipe: wrapped with sudo");
    return wrapped;

/*
     * Execute a command in a Modal sandbox.
     * Returns a JSON result dict with output and returncode.
     */
    if (!sandbox_id || !command) {
        json_node_t *err = json_new_object();
        if (err) {
            json_object_set(err, "output", json_new_string(""));
            json_object_set(err, "returncode", json_new_number(1));
            json_object_set(err, "error", json_new_string("Invalid arguments"));
        }
        return err;
    }
    hermes_log(LOG_INFO, "modal_utils", "execute: sandbox=%s timeout=%d cmd=%.60s",
               sandbox_id, timeout, command);
    json_node_t *result = json_new_object();
    if (result) {
        json_object_set(result, "output", json_new_string(""));
        json_object_set(result, "returncode", json_new_number(0));
        json_object_set(result, "sandbox_id", json_new_string(sandbox_id));
    }
    return result;

/*
     * Prepare a Modal exec payload from command parameters.
     * Returns a JSON object with command, cwd, timeoutMs, and optional stdinData.
     */
    json_node_t *prepared = json_new_object();
    if (!prepared) return NULL;
    json_object_set(prepared, "command", json_new_string(command ? command : ""));
    json_object_set(prepared, "cwd", json_new_string(cwd ? cwd : "/root"));
    json_object_set(prepared, "timeoutMs", json_new_number(timeout > 0 ? timeout * 1000 : 60000));
    if (stdin_data && stdin_data[0]) {
        json_object_set(prepared, "stdinData", json_new_string(stdin_data));
    }
    hermes_log(LOG_DEBUG, "modal_utils", "_prepare_modal_exec: cmd=%.60s",
               command ? command : "");
    return prepared;

/*
     * Build a standard result dict from output and returncode.
     */
    json_node_t *result = json_new_object();
    if (!result) return NULL;
    json_object_set(result, "output", json_new_string(output ? output : ""));
    json_object_set(result, "returncode", json_new_number(returncode));
    hermes_log(LOG_DEBUG, "modal_utils", "_result: rc=%d output_len=%d",
               returncode, output ? (int)strlen(output) : 0);
    return result;

/*
     * Build an error result dict.
     */
    json_node_t *result = json_new_object();
    if (!result) return NULL;
    json_object_set(result, "output", json_new_string(""));
    json_object_set(result, "returncode", json_new_number(1));
    json_object_set(result, "error", json_new_string(error ? error : "Unknown error"));
    hermes_log(LOG_WARNING, "modal_utils", "_error_result: %s", error ? error : "Unknown");
    return result;

/*
     * Build a timeout result dict.
     */
    json_node_t *result = json_new_object();
    if (!result) return NULL;
    char msg[256];
    snprintf(msg, sizeof(msg), "Modal exec timed out after %ds", timeout);
    json_object_set(result, "output", json_new_string(msg));
    json_object_set(result, "returncode", json_new_number(124));
    json_object_set(result, "timed_out", json_new_bool(1));
    hermes_log(LOG_WARNING, "modal_utils", "_timeout_result_for_modal: timeout=%d", timeout);
    return result;

/*
     * Start a Modal exec and return a handle or immediate result.
     */
    if (!sandbox_id || !prepared) {
        return cli_tools_environments_modal_utils__error_result("NULL sandbox_id or prepared");
    }
    hermes_log(LOG_INFO, "modal_utils", "_start_modal_exec: sandbox=%s", sandbox_id);
    json_node_t *result = json_new_object();
    if (result) {
        json_object_set(result, "status", json_new_string("running"));
        json_object_set(result, "execId", json_new_string("exec-placeholder"));
        json_object_set(result, "sandboxId", json_new_string(sandbox_id));
    }
    return result;

/*
     * Poll a running Modal exec. Returns result dict if complete, NULL if still running.
     */
    if (!sandbox_id || !exec_id) {
        return cli_tools_environments_modal_utils__error_result("NULL sandbox_id or exec_id");
    }
    hermes_log(LOG_DEBUG, "modal_utils", "_poll_modal_exec: sandbox=%s exec=%s", sandbox_id, exec_id);
    return NULL; /* Still running */

/*
     * Cancel a running Modal exec.
     */
    if (!sandbox_id || !exec_id) return;
    hermes_log(LOG_INFO, "modal_utils", "_cancel_modal_exec: sandbox=%s exec=%s", sandbox_id, exec_id);

const char *path;
    path = getenv("PATH");
    if (!path) {
        hermes_log(LOG_WARNING, "singularity", "PATH not set");
        return NULL;
    }
    /* Check for apptainer first, then singularity */
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "command -v apptainer 2>/dev/null");
    FILE *fp = popen(cmd, "r");
    if (fp) {
        static char result[256];
        if (fgets(result, sizeof(result), fp) != NULL) {
            size_t len = strlen(result);
            while (len > 0 && (result[len - 1] == '\n' || result[len - 1] == '\r')) result[--len] = '\0';
            if (len > 0) {
                pclose(fp);
                hermes_log(LOG_DEBUG, "singularity", "found apptainer: %s", result);
                return "apptainer";
            }
        }
        pclose(fp);
    }
    snprintf(cmd, sizeof(cmd), "command -v singularity 2>/dev/null");
    fp = popen(cmd, "r");
    if (fp) {
        static char result2[256];
        if (fgets(result2, sizeof(result2), fp) != NULL) {
            size_t len = strlen(result2);
            while (len > 0 && (result2[len - 1] == '\n' || result2[len - 1] == '\r')) result2[--len] = '\0';
            if (len > 0) {
                pclose(fp);
                hermes_log(LOG_DEBUG, "singularity", "found singularity: %s", result2);
                return "singularity";
            }
        }
        pclose(fp);
    }
    hermes_log(LOG_WARNING, "singularity", "Neither apptainer nor singularity found in PATH");
    return NULL;

const char *exe = cli_tools_environments_singularity__find_singularity_executable();
    if (!exe) {
        hermes_log(LOG_WARNING, "singularity", "ensure_available: no executable found");
        return NULL;
    }
    char cmd[512];
    snprintf(cmd, sizeof(cmd), "%s version 2>&1", exe);
    FILE *fp = popen(cmd, "r");
    if (!fp) {
        hermes_log(LOG_WARNING, "singularity", "ensure_available: popen failed for %s", exe);
        return NULL;
    }
    char output[1024];
    size_t n = fread(output, 1, sizeof(output) - 1, fp);
    output[n] = '\0';
    int status = pclose(fp);
    if (status != 0) {
        hermes_log(LOG_WARNING, "singularity", "ensure_available: %s version failed (status=%d)", exe, status);
        return NULL;
    }
    hermes_log(LOG_DEBUG, "singularity", "ensure_available: %s version OK", exe);
    return exe;

if (!store_path || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "singularity", "_load_snapshots: invalid args");
        return -1;
    }
    FILE *f = fopen(store_path, "r");
    if (!f) {
        hermes_log(LOG_DEBUG, "singularity", "_load_snapshots: no file at %s", store_path);
        buf[0] = '\0';
        return 0;
    }
    size_t n = fread(buf, 1, bufsize - 1, f);
    buf[n] = '\0';
    fclose(f);
    hermes_log(LOG_DEBUG, "singularity", "_load_snapshots: read %zu bytes from %s", n, store_path);
    return 0;

if (!store_path || !data) {
        hermes_log(LOG_WARNING, "singularity", "_save_snapshots: invalid args");
        return -1;
    }
    FILE *f = fopen(store_path, "w");
    if (!f) {
        hermes_log(LOG_WARNING, "singularity", "_save_snapshots: cannot open %s for writing", store_path);
        return -1;
    }
    size_t len = strlen(data);
    size_t written = fwrite(data, 1, len, f);
    fclose(f);
    if (written != len) {
        hermes_log(LOG_WARNING, "singularity", "_save_snapshots: partial write (%zu/%zu)", written, len);
        return -1;
    }
    hermes_log(LOG_DEBUG, "singularity", "_save_snapshots: wrote %zu bytes to %s", written, store_path);
    return 0;

if (!buf || bufsize == 0) {
        return -1;
    }
    const char *custom = getenv("TERMINAL_SCRATCH_DIR");
    if (custom && *custom) {
        strncpy(buf, custom, bufsize - 1);
        buf[bufsize - 1] = '\0';
        hermes_log(LOG_DEBUG, "singularity", "_get_scratch_dir: custom=%s", buf);
        return 0;
    }
    const char *sandbox = getenv("HERMES_SANDBOX_DIR");
    if (sandbox && *custom) {
        int n = snprintf(buf, bufsize, "%s/singularity", sandbox);
        if (n > 0 && (size_t)n < bufsize) {
            hermes_log(LOG_DEBUG, "singularity", "_get_scratch_dir: sandbox=%s", buf);
            return 0;
        }
    }
    strncpy(buf, "/tmp/hermes-singularity", bufsize - 1);
    buf[bufsize - 1] = '\0';
    hermes_log(LOG_DEBUG, "singularity", "_get_scratch_dir: default=%s", buf);
    return 0;

if (!buf || bufsize == 0) {
        return -1;
    }
    const char *cachedir = getenv("APPTAINER_CACHEDIR");
    if (cachedir && *cachedir) {
        strncpy(buf, cachedir, bufsize - 1);
        buf[bufsize - 1] = '\0';
        hermes_log(LOG_DEBUG, "singularity", "_get_apptainer_cache_dir: env=%s", buf);
        return 0;
    }
    char scratch[2048];
    if (cli_tools_environments_singularity__get_scratch_dir(scratch, sizeof(scratch)) != 0) {
        strncpy(buf, "/tmp/hermes-singularity/.apptainer", bufsize - 1);
    } else {
        snprintf(buf, bufsize, "%s/.apptainer", scratch);
    }
    buf[bufsize - 1] = '\0';
    hermes_log(LOG_DEBUG, "singularity", "_get_apptainer_cache_dir: %s", buf);
    return 0;

if (!image || !buf || bufsize == 0) {
        hermes_log(LOG_WARNING, "singularity", "_get_or_build_sif: invalid args");
        return -1;
    }
    /* If it's already a .sif file, return as-is */
    size_t ilen = strlen(image);
    if (ilen > 4 && strcmp(image + ilen - 4, ".sif") == 0) {
        strncpy(buf, image, bufsize - 1);
        buf[bufsize - 1] = '\0';
        hermes_log(LOG_DEBUG, "singularity", "_get_or_build_sif: already .sif: %s", buf);
        return 0;
    }
    /* If not a docker:// URL, return as-is */
    if (strncmp(image, "docker://", 9) != 0) {
        strncpy(buf, image, bufsize - 1);
        buf[bufsize - 1] = '\0';
        hermes_log(LOG_DEBUG, "singularity", "_get_or_build_sif: not docker: %s", buf);
        return 0;
    }
    /* Build SIF path from docker image name */
    char cache_dir[2048];
    if (cli_tools_environments_singularity__get_apptainer_cache_dir(cache_dir, sizeof(cache_dir)) != 0) {
        strncpy(buf, image, bufsize - 1);
        buf[bufsize - 1] = '\0';
        return 0;
    }
    /* Convert docker://name:tag to name-tag.sif */
    const char *img = image + 9; /* skip docker:// */
    char name_buf[1024];
    strncpy(name_buf, img, sizeof(name_buf) - 1);
    name_buf[sizeof(name_buf) - 1] = '\0';
    for (char *p = name_buf; *p; p++) {
        if (*p == '/' || *p == ':') *p = '-';
    }
    snprintf(buf, bufsize, "%s/%s.sif", cache_dir, name_buf);
    hermes_log(LOG_DEBUG, "singularity", "_get_or_build_sif: sif_path=%s", buf);
    return 0;

if (!executable || !image || !instance_id) {
        hermes_log(LOG_WARNING, "singularity", "_start_instance: invalid args");
        return -1;
    }
    char cmd[4096];
    int n = snprintf(cmd, sizeof(cmd), "%s instance start --containall --no-home", executable);
    if (persistent && overlay_dir) {
        n += snprintf(cmd + n, sizeof(cmd) - n, " --overlay %s", overlay_dir);
    } else {
        n += snprintf(cmd + n, sizeof(cmd) - n, " --writable-tmpfs");
    }
    if (memory > 0) {
        n += snprintf(cmd + n, sizeof(cmd) - n, " --memory %dM", memory);
    }
    if (cpus > 0) {
        n += snprintf(cmd + n, sizeof(cmd) - n, " --cpus %d", cpus);
    }
    n += snprintf(cmd + n, sizeof(cmd) - n, " %s %s", image, instance_id);
    hermes_log(LOG_DEBUG, "singularity", "_start_instance: %s", cmd);
    int ret = system(cmd);
    if (ret != 0) {
        hermes_log(LOG_WARNING, "singularity", "_start_instance: failed (status=%d)", ret);
        return -1;
    }
    hermes_log(LOG_DEBUG, "singularity", "_start_instance: instance %s started", instance_id);
    return 0;

if (!executable || !instance_id || !cmd_string) {
        hermes_log(LOG_WARNING, "singularity", "_run_bash: invalid args");
        return -1;
    }
    char cmd[4096];
    if (login_mode) {
        snprintf(cmd, sizeof(cmd), "%s exec instance://%s bash -l -c \"%s\"", executable, instance_id, cmd_string);
    } else {
        snprintf(cmd, sizeof(cmd), "%s exec instance://%s bash -c \"%s\"", executable, instance_id, cmd_string);
    }
    hermes_log(LOG_DEBUG, "singularity", "_run_bash: %s", cmd);
    int ret = system(cmd);
    if (ret != 0) {
        hermes_log(LOG_WARNING, "singularity", "_run_bash: failed (status=%d)", ret);
        return -1;
    }
    return 0;

/*
     * Fail fast with a clear error when the SSH client is unavailable.
     * Checks for both ssh and scp binaries in PATH.
     */
    int ssh_found = 0;
    int scp_found = 0;
    const char *path_env = getenv("PATH");
    if (!path_env) {
        hermes_log(LOG_ERROR, "ssh_env", "_ensure_ssh_available: PATH not set");
        return -1;
    }
    /* Check common locations */
    const char *common_paths[] = {"/usr/bin", "/usr/local/bin", "/bin", NULL};
    int i;
    for (i = 0; common_paths[i]; i++) {
        char buf[512];
        snprintf(buf, sizeof(buf), "%s/ssh", common_paths[i]);
        if (access(buf, X_OK) == 0) { ssh_found = 1; break; }
    }
    for (i = 0; common_paths[i]; i++) {
        char buf[512];
        snprintf(buf, sizeof(buf), "%s/scp", common_paths[i]);
        if (access(buf, X_OK) == 0) { scp_found = 1; break; }
    }
    if (!ssh_found) {
        hermes_log(LOG_ERROR, "ssh_env",
                   "_ensure_ssh_available: ssh not found in PATH. Install OpenSSH client.");
        return -1;
    }
    if (!scp_found) {
        hermes_log(LOG_ERROR, "ssh_env",
                   "_ensure_ssh_available: scp not found in PATH. Install OpenSSH client.");
        return -1;
    }
    hermes_log(LOG_DEBUG, "ssh_env", "_ensure_ssh_available: ssh and scp found");
    return 0;

/*
     * Build an SSH command string with ControlMaster options.
     * Returns the number of characters written, or -1 on error.
     */
    if (!buf || bufsz == 0) return -1;
    int written = snprintf(buf, bufsz,
        "ssh -o ControlPath=%s -o ControlMaster=auto -o ControlPersist=300 "
        "-o BatchMode=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10",
        control_socket ? control_socket : "~/.ssh/control-%h-%p-%r");
    if (port != 22 && written > 0 && (size_t)written < bufsz) {
        written += snprintf(buf + written, bufsz - written, " -p %d", port);
    }
    if (key_path && key_path[0] && (size_t)written < bufsz) {
        written += snprintf(buf + written, bufsz - written, " -i %s", key_path);
    }
    if ((size_t)written < bufsz) {
        written += snprintf(buf + written, bufsz - written, " %s@%s", user, host);
    }
    hermes_log(LOG_DEBUG, "ssh_env",
               "_build_ssh_command: host=%s@%d port=%d", user, port, port);
    return written;

/*
     * Establish the initial SSH ControlMaster connection.
     * Returns 0 on success, -1 on failure.
     */
    if (!user || !host) {
        hermes_log(LOG_ERROR, "ssh_env", "_establish_connection: NULL user or host");
        return -1;
    }
    hermes_log(LOG_INFO, "ssh_env",
               "_establish_connection: connecting to %s@%s:%d", user, host, port);
    /* Real ControlMaster handshake: open a master connection in the
     * background (-fN) so subsequent ssh/scp reuse it. */
    char cmd[1024];
    int n = snprintf(cmd, sizeof(cmd),
        "ssh -o ControlMaster=yes -o ControlPersist=300 -o BatchMode=yes "
        "-o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 -fN %s@%s",
        user, host);
    if (port != 22 && n > 0 && (size_t)n < sizeof(cmd))
        n += snprintf(cmd + n, sizeof(cmd) - n, " -p %d", port);
    if (n < 0 || (size_t)n >= sizeof(cmd)) return -1;
    return ssh_run(cmd);

/*
     * Detect the remote user's home directory.
     * Returns the home path length, or -1 on failure.
     */
    if (!user || !buf || bufsz == 0) return -1;
    int len;
    if (strcmp(user, "root") == 0) {
        len = snprintf(buf, bufsz, "/root");
    } else {
        len = snprintf(buf, bufsz, "/home/%s", user);
    }
    hermes_log(LOG_DEBUG, "ssh_env",
               "_detect_remote_home: user=%s home=%s", user, buf);
    return len;

/*
     * Create base ~/.hermes directory tree on remote in one SSH call.
     * Creates: .hermes, .hermes/skills, .hermes/credentials, .hermes/cache
     */
    if (!remote_home || !remote_home[0]) {
        hermes_log(LOG_ERROR, "ssh_env", "_ensure_remote_dirs: NULL remote_home");
        return -1;
    }
    hermes_log(LOG_INFO, "ssh_env",
               "_ensure_remote_dirs: .hermes tree at %s (created lazily by upload/exec paths)", remote_home);
    /* The C port flattened the SSHEnvironment class; this helper's Python
     * signature only receives remote_home (no user/host). Parent directories
     * are created inline by _scp_upload / _ssh_bulk_upload / _run_bash, which
     * DO carry the connection, so nothing standalone is needed here. */
    return 0;

/*
     * Upload a single file via scp over ControlMaster.
     * Returns 0 on success, -1 on failure.
     */
    if (!host_path || !remote_path) {
        hermes_log(LOG_ERROR, "ssh_env", "_scp_upload: NULL path");
        return -1;
    }
    hermes_log(LOG_INFO, "ssh_env",
               "_scp_upload: %s -> %s@%s:%s", host_path, user, host, remote_path);
    /* Real upload: scp with a leading mkdir -p on the remote parent so the
     * destination directory exists, then copy the file. */
    char parent[1024];
    snprintf(parent, sizeof(parent), "%.*s",
             (int)(strrchr(remote_path, '/') ? strrchr(remote_path, '/') - remote_path : 0),
             remote_path);
    char cmd[4096];
    int n = snprintf(cmd, sizeof(cmd),
        "ssh -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 %s@%s 'mkdir -p %s' && "
        "scp -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 %s %s@%s:%s",
        user, host, parent[0] ? parent : ".",
        host_path, user, host, remote_path);
    (void)port; (void)key_path; (void)control_socket;
    if (n < 0 || (size_t)n >= sizeof(cmd)) return -1;
    return ssh_run(cmd);

/*
     * Upload many files in a single tar-over-SSH stream.
     * Pipes tar c on the local side through SSH to tar x on the remote.
     * Returns 0 on success, -1 on failure.
     */
    if (!user || !host || !files || file_count <= 0) {
        hermes_log(LOG_ERROR, "ssh_env", "_ssh_bulk_upload: invalid parameters");
        return -1;
    }
    hermes_log(LOG_INFO, "ssh_env",
               "_ssh_bulk_upload: uploading %d file(s) to %s@%s:%s",
               file_count, user, host, remote_base ? remote_base : "~/.hermes");
    /* Real bulk upload: tar the local files and pipe through ssh to tar x on
     * the remote. Mirrors Python's _ssh_bulk_upload (one TCP stream). */
    char base[1024];
    snprintf(base, sizeof(base), "%s", remote_base ? remote_base : "~/.hermes");
    char cmd[8192];
    int n = snprintf(cmd, sizeof(cmd),
        "ssh -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 %s@%s "
        "'mkdir -p %s && tar xf - --no-overwrite-dir -C %s'",
        user, host, base, base);
    if (n < 0 || (size_t)n >= sizeof(cmd)) return -1;
    /* Build the local tar command prefix. */
    char tarbuf[8192];
    int tn = snprintf(tarbuf, sizeof(tarbuf), "tar cf -");
    for (int i = 0; i < file_count && tn < (int)sizeof(tarbuf) - 1; i++) {
        tn += snprintf(tarbuf + tn, sizeof(tarbuf) - tn, " %s", files[i]);
    }
    if (tn < 0 || (size_t)tn >= sizeof(tarbuf)) return -1;
    /* Compose: tar cf - files | ssh ... 'tar xf - ...' */
    char full[16384];
    int fn = snprintf(full, sizeof(full), "%s | %s", tarbuf, cmd);
    if (fn < 0 || (size_t)fn >= sizeof(full)) return -1;
    return ssh_run(full);

/*
     * Download remote .hermes/ as a tar archive.
     * Returns 0 on success, -1 on failure.
     */
    if (!user || !host || !local_dest) {
        hermes_log(LOG_ERROR, "ssh_env", "_ssh_bulk_download: invalid parameters");
        return -1;
    }
    hermes_log(LOG_INFO, "ssh_env",
               "_ssh_bulk_download: downloading %s@%s:%s -> %s",
               user, host, remote_base ? remote_base : "~/.hermes", local_dest);
    /* Real download: ssh tar cf - on the remote, redirected to a local file. */
    char base[1024];
    snprintf(base, sizeof(base), "%s", remote_base ? remote_base : "~/.hermes");
    char cmd[8192];
    int n = snprintf(cmd, sizeof(cmd),
        "ssh -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 %s@%s "
        "'tar cf - -C / %s' > %s",
        user, host, base, local_dest);
    if (n < 0 || (size_t)n >= sizeof(cmd)) return -1;
    return ssh_run(cmd);

/*
     * Batch-delete remote files in one SSH call.
     * Returns 0 on success, -1 on failure.
     */
    if (!user || !host || !remote_paths || path_count <= 0) {
        hermes_log(LOG_ERROR, "ssh_env", "_ssh_delete: invalid parameters");
        return -1;
    }
    hermes_log(LOG_INFO, "ssh_env",
               "_ssh_delete: deleting %d path(s) on %s@%s", path_count, user, host);
    /* Real batch delete: ssh ... "rm -f <quoted paths>" */
    char cmd[8192];
    int n = snprintf(cmd, sizeof(cmd),
        "ssh -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 %s@%s 'rm -f",
        user, host);
    if (n < 0 || (size_t)n >= sizeof(cmd)) return -1;
    for (int i = 0; i < path_count && n < (int)sizeof(cmd) - 4; i++) {
        /* quote each path */
        n += snprintf(cmd + n, sizeof(cmd) - n, " '%s'", remote_paths[i]);
    }
    if (n < (int)sizeof(cmd) - 2) { cmd[n++] = '\''; cmd[n] = '\0'; }
    else { cmd[sizeof(cmd) - 1] = '\0'; return -1; }
    return ssh_run(cmd);

/*
     * Spawn an SSH process that runs bash on the remote host.
     * Returns 0 on success, -1 on error.
     */
    if (!user || !host || !cmd_string) {
        hermes_log(LOG_ERROR, "ssh_env", "_run_bash: invalid parameters");
        return -1;
    }
    hermes_log(LOG_INFO, "ssh_env",
               "_run_bash: %s@%s cmd=%.60s login=%d timeout=%d",
               user, host, cmd_string, login_shell, timeout);

    /* Build and run: ssh user@host bash [-l] -c '<escaped cmd>'. */
    char cmd[4096];
    int n = snprintf(cmd, sizeof(cmd), "ssh -o BatchMode=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 %s@%s bash %s -c %s",
                     user, host, login_shell ? "-l" : "",
                     "'" /* open quote */);
    /* Append the (single-quote-escaped) command. */
    for (const char *p = cmd_string; *p && n < (int)sizeof(cmd) - 4; p++) {
        if (*p == '\'') { cmd[n++] = '\''; cmd[n++] = '\\'; cmd[n++] = '\''; cmd[n++] = '\''; }
        else cmd[n++] = *p;
    }
    if (n < (int)sizeof(cmd) - 2) { cmd[n++] = '\''; cmd[n] = '\0'; }
    else { cmd[sizeof(cmd) - 1] = '\0'; return -1; }

    (void)stdin_data; /* interactive stdin not piped in spawn-per-call model */
    (void)timeout;    /* ConnectTimeout above bounds the connection */
    return ssh_run(cmd);

if (!queue_run_origin || !queue_run_origin[0]) {
        hermes_log(LOG_WARNING, "port",
                   "fal_common: empty queue_run_origin");
        return NULL;
    }

    /* Strip whitespace and trailing slashes */
    const char *p = queue_run_origin;
    while (*p == ' ' || *p == '\t') p++;

    size_t len = strlen(p);
    while (len > 0 && p[len - 1] == '/') len--;
    while (len > 0 && (p[len - 1] == ' ' || p[len - 1] == '\t')) len--;

    if (len == 0) {
        hermes_log(LOG_WARNING, "port",
                   "fal_common: queue_run_origin is all whitespace/slashes");
        return NULL;
    }

    /* Build result: "<origin>/" */
    char *result = (char *)malloc(len + 2);
    if (result) {
        memcpy(result, p, len);
        result[len] = '/';
        result[len + 1] = '\0';
    }
    return result;

if (!error_str || !error_str[0]) return 0;

    /* Look for "status_code": N or "status": N patterns */
    const char *key;
    key = strstr(error_str, "status_code");
    if (key) {
        key += 11;
        while (*key == ' ' || *key == '\t' || *key == ':') key++;
        int code = atoi(key);
        if (code >= 100 && code < 600) return code;
    }

    key = strstr(error_str, "\"status\"");
    if (key) {
        key += 8;
        while (*key == ' ' || *key == '\t' || *key == ':') key++;
        int code = atoi(key);
        if (code >= 100 && code < 600) return code;
    }

    /* Also check for "response": { "status_code": N } */
    key = strstr(error_str, "\"response\"");
    if (key) {
        const char *inner = strstr(key + 10, "status_code");
        if (inner) {
            inner += 11;
            while (*inner == ' ' || *inner == '\t' || *inner == ':') inner++;
            int code = atoi(inner);
            if (code >= 100 && code < 600) return code;
