    /* Validate scheme (Python: only http/https) */
    if (strncmp(url, "http://", 7) != 0 && strncmp(url, "https://", 8) != 0) {
        normalized_out[0] = '\0';
        return -1;
    }

    /* Split scheme://netloc/path?query#fragment */
    const char *auth_end = strstr(url, "://");
    const char *rest = auth_end + 3;
    char scheme[9];
    size_t sl = auth_end - url;
    if (sl >= sizeof(scheme)) { normalized_out[0] = '\0'; return -1; }
    memcpy(scheme, url, sl); scheme[sl] = '\0';

    /* Find end of netloc (first / ? #) */
    size_t netloc_len = 0;
    while (rest[netloc_len] && rest[netloc_len] != '/' &&
           rest[netloc_len] != '?' && rest[netloc_len] != '#')
        netloc_len++;

    char netloc[1024];
    if (netloc_len >= sizeof(netloc)) { normalized_out[0] = '\0'; return -1; }
    memcpy(netloc, rest, netloc_len);
    netloc[netloc_len] = '\0';

    const char *after = rest + netloc_len;
    const char *path = (*after == '/') ? after : "/";
    const char *frag = strchr(after, '#');

    /* Separate hostname from netloc (strip userinfo@ and :port) */
    char hostname[256];
    const char *at = strrchr(netloc, '@');
    const char *host_start = at ? at + 1 : netloc;
    size_t hlen = strlen(host_start);
    /* strip port (but not inside IPv6 literal) */
    const char *colon = strrchr(host_start, ':');
    const char *port_str = NULL;
    if (colon && strchr(colon, ']') == NULL) {
        port_str = colon + 1;
        hlen = (size_t)(colon - host_start);
    }
    if (hlen >= sizeof(hostname)) { normalized_out[0] = '\0'; return -1; }
    memcpy(hostname, host_start, hlen); hostname[hlen] = '\0';

    /* IDNA-encode each dot-separated label if it contains non-ASCII.
     * Note: we must NOT mutate hcopy in place (strtok_r relies on its own
     * null-terminators); instead encode into a scratch buffer and append that. */
    char enc_host[1024];
    enc_host[0] = '\0';
    char *tokctx = NULL;
    char *hcopy = strdup(hostname);
    char *label = strtok_r(hcopy, ".", &tokctx);
    int first = 1;
    while (label) {
        const char *out_label = label;
        int has_nonascii = 0;
        for (size_t k = 0; label[k]; k++) if ((unsigned char)label[k] >= 0x80) has_nonascii = 1;
        char enc[256];
        if (has_nonascii) {
            if (punycode_encode_label(label, strlen(label), enc, sizeof(enc)) == 0)
                out_label = enc;
        }
        if (!first) strncat(enc_host, ".", sizeof(enc_host) - strlen(enc_host) - 1);
        strncat(enc_host, out_label, sizeof(enc_host) - strlen(enc_host) - 1);
        first = 0;
        label = strtok_r(NULL, ".", &tokctx);
    }
    free(hcopy);

    /* Rebuild netloc = userinfo + encoded host + port */
    char final_netloc[1024];
    size_t need = 0;
    if (at) need = (size_t)(host_start - netloc);            /* userinfo incl '@' */
    need += strlen(enc_host);
    if (port_str) need += 1 + strlen(port_str);
    if (need + 1 > sizeof(final_netloc)) { normalized_out[0] = '\0'; return -1; }
    final_netloc[0] = '\0';
    if (at) { strncat(final_netloc, netloc, (size_t)(host_start - netloc)); }
    strncat(final_netloc, enc_host, sizeof(final_netloc) - strlen(final_netloc) - 1);
    if (port_str) {
        strncat(final_netloc, ":", sizeof(final_netloc) - strlen(final_netloc) - 1);
        strncat(final_netloc, port_str, sizeof(final_netloc) - strlen(final_netloc) - 1);
    }

    /* Percent-encode path / query / fragment */
    char enc_path[2048], enc_query[2048], enc_frag[2048];
    const char *path_part = path;
    const char *qstart = strchr(path_part, '?');
    const char *fstart = strchr(path_part, '#');
    size_t path_only_len = strlen(path_part);
    if (qstart) path_only_len = (size_t)(qstart - path_part);
    else if (fstart) path_only_len = (size_t)(fstart - path_part);

    char path_only[2048];
    memcpy(path_only, path_part, path_only_len); path_only[path_only_len] = '\0';
    percent_encode(path_only, enc_path, sizeof(enc_path), "/%:@!$&'()*+,;=");
    const char *qpart = (qstart || frag) ? strchr(after, '?') : NULL;
    if (qpart) {
        percent_encode(qpart + 1, enc_query, sizeof(enc_query), "/%:@!$&'()*+,;=?");
    } else enc_query[0] = '\0';
    const char *fpart = strchr(after, '#');
    if (fpart) {
        percent_encode(fpart + 1, enc_frag, sizeof(enc_frag), "/%:@!$'()*+,;=?");
    } else enc_frag[0] = '\0';

    int w = snprintf(normalized_out, norm_size, "%s://%s%s%s%s%s",
                     scheme, final_netloc,
                     enc_path,
                     qpart ? "?" : "", qpart ? enc_query : "",
                     fpart ? "#" : "", fpart ? enc_frag : "");
    if (w < 0 || (size_t)w >= norm_size) { normalized_out[0] = '\0'; return -1; }
    hermes_log(LOG_DEBUG, "url_safety", "normalize: %s", normalized_out);
    return 0;

FILE *f = fopen(config_path, "r");
    if (!f) return 0;
    char line[1024];
    int in_security = 0, in_browser = 0;
    int found = 0;
    while (fgets(line, sizeof(line), f)) {
        /* measure indent */
        size_t indent = 0;
        while (line[indent] == ' ' || line[indent] == '\t') indent++;
        char *colon = strchr(line, ':');
        if (!colon) continue;
        size_t key_len = (size_t)(colon - line) - indent;
        char key[256];
        if (key_len >= sizeof(key)) { continue; }
        memcpy(key, line + indent, key_len);
        key[key_len] = '\0';
        /* trim trailing space from key */
        while (key_len > 0 && (key[key_len-1] == ' ' || key[key_len-1] == '\t')) key[--key_len] = '\0';

        if (indent == 0 && strcmp(key, "security") == 0) { in_security = 1; in_browser = 0; continue; }
        if (indent == 0 && strcmp(key, "browser") == 0) { in_browser = 1; in_security = 0; continue; }
        if (indent > 0 && strcmp(key, "security") == 0) { in_security = 1; in_browser = 0; continue; }
        if (indent > 0 && strcmp(key, "browser") == 0) { in_browser = 1; in_security = 0; continue; }

        if ((in_security || in_browser) && strcmp(key, "allow_private_urls") == 0) {
            char *v = colon + 1;
            while (*v == ' ' || *v == '\t') v++;
            size_t vl = strlen(v);
            while (vl > 0 && (v[vl-1] == '\r' || v[vl-1] == '\n' ||
                   v[vl-1] == ' ' || v[vl-1] == '\t')) vl--;
            if (vl >= 4 && strncmp(v, "true", 4) == 0) { found = 1; break; }
            if (vl >= 1 && (v[0] == '1')) { found = 1; break; }
        }
    }
    fclose(f);
    return found;

if (!ip_str) return 1;

    struct in_addr addr4;
    struct in6_addr addr6;

    if (inet_pton(AF_INET, ip_str, &addr4) == 1) {
        /* IPv4 checks */
        uint32_t ip = ntohl(addr4.s_addr);

        /* 169.254.0.0/16 (link-local) */
        if ((ip & 0xFFFF0000) == 0xA9FE0000) return 1;
        /* 127.0.0.0/8 (loopback) */
        if ((ip & 0xFF000000) == 0x7F000000) return 1;
        /* 10.0.0.0/8 (private) */
        if ((ip & 0xFF000000) == 0x0A000000) return 1;
        /* 172.16.0.0/12 (private) */
        if ((ip & 0xFFF00000) == 0xAC100000) return 1;
        /* 192.168.0.0/16 (private) */
        if ((ip & 0xFFFF0000) == 0xC0A80000) return 1;
        /* 100.64.0.0/10 (CGNAT) */
        if ((ip & 0xFFC00000) == 0x64400000) return 1;
        /* 0.0.0.0/8 (unspecified) */
        if ((ip & 0xFF000000) == 0x00000000) return 1;
        /* 224.0.0.0/4 (multicast) */
        if ((ip & 0xF0000000) == 0xE0000000) return 1;
        /* 240.0.0.0/4 (reserved) */
        if ((ip & 0xF0000000) == 0xF0000000) return 1;

        return 0;
    }

    if (inet_pton(AF_INET6, ip_str, &addr6) == 1) {
        /* IPv4-mapped IPv6: ::ffff:x.x.x.x */
        if (IN6_IS_ADDR_V4MAPPED(&addr6)) {
            char ipv4[INET_ADDRSTRLEN];
            snprintf(ipv4, sizeof(ipv4), "%d.%d.%d.%d",
                     addr6.s6_addr[12], addr6.s6_addr[13],
                     addr6.s6_addr[14], addr6.s6_addr[15]);
            return cli_tools_url_safety__is_blocked_ip(ipv4);
        }
        /* IPv6 loopback ::1 */
        if (IN6_IS_ADDR_LOOPBACK(&addr6)) return 1;
        /* IPv6 link-local fe80::/10 */
        if ((addr6.s6_addr[0] & 0xFF) == 0xFE && (addr6.s6_addr[1] & 0xC0) == 0x80) return 1;
        /* IPv6 unique local fc00::/7 */
        if ((addr6.s6_addr[0] & 0xFE) == 0xFC) return 1;
        /* IPv6 multicast ff00::/8 */
        if (addr6.s6_addr[0] == 0xFF) return 1;
        /* IPv6 unspecified :: */
        if (IN6_IS_ADDR_UNSPECIFIED(&addr6)) return 1;
        return 0;
    }

    /* If we can't parse it, block it */
    return 1;

if (!url) return 0;

    /* Extract hostname from URL */
    const char *host_start = strstr(url, "://");
    if (!host_start) host_start = url;
    else host_start += 3;

    char hostname[256];
    size_t i = 0;
    while (*host_start && *host_start != '/' && *host_start != ':' &&
           *host_start != '?' && *host_start != '#' && i < sizeof(hostname) - 1) {
        hostname[i++] = tolower((unsigned char)*host_start++);
    }
    hostname[i] = '\0';

    /* Remove trailing dot */
    while (i > 0 && hostname[i-1] == '.') hostname[--i] = '\0';

    if (hostname[0] == '\0') return 0;

    /* Check blocked hostnames */
    for (int b = 0; BLOCKED_HOSTNAMES[b]; b++) {
        if (strcasecmp(hostname, BLOCKED_HOSTNAMES[b]) == 0) {
            hermes_log(LOG_WARNING, "url_safety", "Blocked hostname: %s", hostname);
            return 1;
        }
    }

    /* Check if hostname is a literal IP */
    if (cli_tools_url_safety__is_blocked_ip(hostname)) {
        /* Check if it's specifically a cloud metadata IP */
        struct in_addr addr4;
        if (inet_pton(AF_INET, hostname, &addr4) == 1) {
            uint32_t ip = ntohl(addr4.s_addr);
            /* 169.254.169.254 (AWS/GCP/Azure metadata) */
            if (ip == 0xA9FEA9FE) return 1;
            /* 169.254.170.2 (AWS ECS) */
            if (ip == 0xA9FEAA02) return 1;
            /* 169.254.169.253 (Azure) */
            if (ip == 0xA9FEA9FD) return 1;
            /* 100.100.100.200 (Alibaba) */
            if (ip == 0x646464C8) return 1;
        }
    }

    /* Try DNS resolution and check answers */
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int ret = getaddrinfo(hostname, NULL, &hints, &res);
    if (ret != 0) return 0; /* DNS failure = not always-blocked */

    for (struct addrinfo *p = res; p; p = p->ai_next) {
        char ip_str[INET6_ADDRSTRLEN];
        if (p->ai_family == AF_INET) {
            struct sockaddr_in *sin = (struct sockaddr_in *)p->ai_addr;
            inet_ntop(AF_INET, &sin->sin_addr, ip_str, sizeof(ip_str));
        } else if (p->ai_family == AF_INET6) {
            struct sockaddr_in6 *sin6 = (struct sockaddr_in6 *)p->ai_addr;
            inet_ntop(AF_INET6, &sin6->sin6_addr, ip_str, sizeof(ip_str));
        } else {
            continue;
        }

        /* Check against always-blocked IPs */
        struct in_addr addr4;
        if (inet_pton(AF_INET, ip_str, &addr4) == 1) {
            uint32_t ip = ntohl(addr4.s_addr);
            if (ip == 0xA9FEA9FE || ip == 0xA9FEAA02 ||
                ip == 0xA9FEA9FD || ip == 0x646464C8) {
                freeaddrinfo(res);
                hermes_log(LOG_WARNING, "url_safety", "Blocked metadata IP: %s -> %s",
                           hostname, ip_str);
                return 1;
            }
        }
    }

    freeaddrinfo(res);
    return 0;

if (!hostname || !scheme) return 0;
    if (strcmp(scheme, "https") != 0) return 0;

    for (int i = 0; TRUSTED_PRIVATE_HOSTS[i]; i++) {
        if (strcasecmp(hostname, TRUSTED_PRIVATE_HOSTS[i]) == 0) return 1;
    }
    return 0;

if (!url) return 0;

    /* Extract hostname and scheme */
    const char *host_start = strstr(url, "://");
    if (!host_start) return 0;
    const char *scheme = url;
    size_t scheme_len = (size_t)(host_start - url);

    char scheme_buf[16];
    snprintf(scheme_buf, sizeof(scheme_buf), "%.*s", (int)scheme_len, scheme);

    if (strcmp(scheme_buf, "http") != 0 && strcmp(scheme_buf, "https") != 0) {
        hermes_log(LOG_WARNING, "url_safety", "Unsupported scheme: %s", scheme_buf);
        return 0;
    }

    host_start += 3;
    char hostname[256];
    size_t i = 0;
    while (*host_start && *host_start != '/' && *host_start != ':' &&
           *host_start != '?' && *host_start != '#' && i < sizeof(hostname) - 1) {
        hostname[i++] = tolower((unsigned char)*host_start++);
    }
    hostname[i] = '\0';
    while (i > 0 && hostname[i-1] == '.') hostname[--i] = '\0';

    if (hostname[0] == '\0') return 0;

    /* Block known internal hostnames */
    for (int b = 0; BLOCKED_HOSTNAMES[b]; b++) {
        if (strcasecmp(hostname, BLOCKED_HOSTNAMES[b]) == 0) {
            hermes_log(LOG_WARNING, "url_safety", "Blocked hostname: %s", hostname);
            return 0;
        }
    }

    int allow_all_private = cli_tools_url_safety__global_allow_private_urls();
    int allow_private_ip = cli_tools_url_safety__allows_private_ip_resolution(hostname, scheme_buf);

    /* Resolve and check IPs */
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int ret = getaddrinfo(hostname, NULL, &hints, &res);
    if (ret != 0) {
        hermes_log(LOG_WARNING, "url_safety", "DNS failed for: %s", hostname);
        return 0; /* Fail closed */
    }

    for (struct addrinfo *p = res; p; p = p->ai_next) {
        char ip_str[INET6_ADDRSTRLEN];
        if (p->ai_family == AF_INET) {
            struct sockaddr_in *sin = (struct sockaddr_in *)p->ai_addr;
            inet_ntop(AF_INET, &sin->sin_addr, ip_str, sizeof(ip_str));
        } else if (p->ai_family == AF_INET6) {
            struct sockaddr_in6 *sin6 = (struct sockaddr_in6 *)p->ai_addr;
            inet_ntop(AF_INET6, &sin6->sin6_addr, ip_str, sizeof(ip_str));
        } else {
            continue;
        }

        /* Always block cloud metadata IPs */
        struct in_addr addr4;
        if (inet_pton(AF_INET, ip_str, &addr4) == 1) {
            uint32_t ip = ntohl(addr4.s_addr);
            if (ip == 0xA9FEA9FE || ip == 0xA9FEAA02 ||
                ip == 0xA9FEA9FD || ip == 0x646464C8 ||
                (ip & 0xFFFF0000) == 0xA9FE0000) {
                freeaddrinfo(res);
                hermes_log(LOG_WARNING, "url_safety", "Blocked metadata: %s -> %s",
                           hostname, ip_str);
                return 0;
            }
        }

        if (!allow_all_private && !allow_private_ip && cli_tools_url_safety__is_blocked_ip(ip_str)) {
            freeaddrinfo(res);
            hermes_log(LOG_WARNING, "url_safety", "Blocked private: %s -> %s",
                       hostname, ip_str);
            return 0;
        }
    }

    freeaddrinfo(res);
    return 1;

if (!url || !result_out) return -1;

    /* Port of Python tools/url_safety.py:async_is_safe_url.
     * Python offloads DNS resolution off the event loop via asyncio.to_thread();
     * in C there is no event loop, so we call the synchronous resolver directly.
     * The behavior (SSRF block decision) is identical. */
    *result_out = cli_tools_url_safety_is_safe_url(url);
    return 0;

/*
     * Read the video_gen section from config.yaml.
     * Returns a JSON object with provider, model, etc. or empty dict on error.
     */
    json_node_t *section = json_new_object();
    if (!section) {
        hermes_log(LOG_WARNING, "video_gen", "_read_video_gen_section: failed to create JSON object");
        return json_new_object();
    }
    hermes_log(LOG_DEBUG, "video_gen", "_read_video_gen_section: reading video_gen config section");
    /* Config is loaded by hermes_config_load; this function builds the JSON
     * representation for the video_gen config section. */
    json_object_set(section, "provider", json_new_null());
    json_object_set(section, "model", json_new_null());
    json_object_set(section, "enabled", json_new_bool(0));
    return section;

/*
     * Return the configured video generation provider name, or NULL if not set.
     */
    json_node_t *section = cli_tools_video_generation_tool__read_video_gen_section();
    if (!section) return NULL;
    const char *provider = NULL;
    json_node_t *prov_node = json_object_get(section, "provider");
    if (prov_node && json_node_is_string(prov_node)) {
        provider = json_node_get_string(prov_node);
        if (provider && strlen(provider) > 0 && strlen(provider) < bufsz) {
            strncpy(buf, provider, bufsz - 1);
            buf[bufsz - 1] = '\0';
            hermes_log(LOG_DEBUG, "video_gen", "_read_configured_video_provider: %s", buf);
        } else {
            provider = NULL;
        }
    }
    return provider ? buf : NULL;

/*
     * Return the configured video generation model name, or NULL if not set.
     */
    json_node_t *section = cli_tools_video_generation_tool__read_video_gen_section();
    if (!section) return NULL;
    const char *model = NULL;
    json_node_t *model_node = json_object_get(section, "model");
    if (model_node && json_node_is_string(model_node)) {
        model = json_node_get_string(model_node);
        if (model && strlen(model) > 0 && strlen(model) < bufsz) {
            strncpy(buf, model, bufsz - 1);
            buf[bufsz - 1] = '\0';
            hermes_log(LOG_DEBUG, "video_gen", "_read_configured_video_model: %s", buf);
        } else {
            model = NULL;
        }
    }
    return model ? buf : NULL;

/*
     * Return 1 when at least one registered provider reports available.
     * Triggers plugin discovery (idempotent) so user-installed plugins are
     * visible to the toolset gate.
     */
    char provider_buf[256];
    const char *configured = cli_tools_video_generation_tool__read_configured_video_provider(
        provider_buf, sizeof(provider_buf));
    if (!configured || !configured[0]) {
        hermes_log(LOG_DEBUG, "video_gen", "check_requirements: no provider configured");
        return 0;
    }
    hermes_log(LOG_DEBUG, "video_gen", "check_requirements: provider=%s available=1", configured);
    return 1;

/*
     * Build a JSON error response for missing provider.
     */
    json_node_t *err = json_new_object();
    if (!err) return NULL;
    json_object_set(err, "error", json_new_string("No video generation backend is configured."));
    json_object_set(err, "error_type", json_new_string("no_provider_configured"));
    json_object_set(err, "video", json_new_null());
    if (configured && configured[0]) {
        json_object_set(err, "provider", json_new_string(configured));
        hermes_log(LOG_WARNING, "video_gen", "_missing_provider_error: provider=%s not registered", configured);
    } else {
        hermes_log(LOG_WARNING, "video_gen", "_missing_provider_error: no provider configured");
    }
    return err;

/*
     * Build a JSON error response for missing provider.
     */
    json_node_t *err = json_new_object();
    if (!err) return NULL;
    json_object_set(err, "error", json_new_string("No video generation backend is configured."));
    json_object_set(err, "error_type", json_new_string("no_provider_configured"));
    json_object_set(err, "video", json_new_null());
    if (configured && configured[0]) {
        json_object_set(err, "provider", json_new_string(configured));
        hermes_log(LOG_WARNING, "video_gen", "_missing_provider_error: provider=%s not registered", configured);
    } else {
        hermes_log(LOG_WARNING, "video_gen", "_missing_provider_error: no provider configured");
    }
    return err;

/*
     * Normalize reference image URLs from various input formats.
     * Accepts a single string, a list of strings, or NULL.
     * Returns a JSON array of strings or NULL.
     */
    if (!value) return NULL;
    json_node_t *result = json_new_array();
    if (!result) return NULL;
    if (json_node_is_string(value)) {
        const char *s = json_node_get_string(value);
        if (s && *s) {
            /* Trim whitespace */
            while (*s == ' ') s++;
            size_t len = strlen(s);
            while (len > 0 && s[len-1] == ' ') len--;
            if (len > 0) {
                char *trimmed = (char*)malloc(len + 1);
                if (trimmed) {
                    memcpy(trimmed, s, len);
                    trimmed[len] = '\0';
                    json_array_append(result, json_new_string(trimmed));
                    free(trimmed);
                }
            }
        }
    } else if (json_node_is_array(value)) {
        int n = json_array_count(value);
        int i;
        for (i = 0; i < n; i++) {
            json_node_t *item = json_array_get(value, i);
            if (json_node_is_string(item)) {
                const char *s = json_node_get_string(item);
                if (s && *s) {
                    json_array_append(result, json_new_string(s));
                }
            }
        }
    }
    if (json_array_count(result) == 0) {
        return NULL;
    }
    return result;

/*
     * Main handler for the video_generate tool.
     * Validates prompt, resolves provider, dispatches to provider.generate().
     * Returns a JSON result dict or error response.
     */
    if (!args || !json_node_is_object(args)) {
        return cli_tools_video_generation_tool__missing_provider_error(NULL);
    }
    /* Extract and validate prompt */
    json_node_t *prompt_node = json_object_get(args, "prompt");
    if (!prompt_node || !json_node_is_string(prompt_node)) {
        json_node_t *err = json_new_object();
        if (err) {
            json_object_set(err, "error", json_new_string("prompt is required for video generation"));
            json_object_set(err, "video", json_new_null());
        }
        return err;
    }
    const char *prompt = json_node_get_string(prompt_node);
    size_t prompt_len = prompt ? strlen(prompt) : 0;
    while (prompt_len > 0 && prompt[0] == ' ') { prompt++; prompt_len--; }
    if (prompt_len == 0) {
        json_node_t *err = json_new_object();
        if (err) {
            json_object_set(err, "error", json_new_string("prompt is required for video generation"));
            json_object_set(err, "video", json_new_null());
        }
        return err;
    }
    hermes_log(LOG_INFO, "video_gen", "_handle_video_generate: prompt=%.60s...", prompt);
    /* Check provider availability */
    void *provider = cli_tools_video_generation_tool__resolve_active_provider();
    if (!provider) {
        char provider_buf[256];
        const char *configured = cli_tools_video_generation_tool__read_configured_video_provider(
            provider_buf, sizeof(provider_buf));
        return cli_tools_video_generation_tool__missing_provider_error(configured);
    }
    /* Build result placeholder — actual generation is async via provider plugin */
    json_node_t *result = json_new_object();
    if (result) {
        json_object_set(result, "status", json_new_string("queued"));
        json_object_set(result, "prompt", json_new_string(prompt));
        json_object_set(result, "video", json_new_null());
        json_object_set(result, "message", json_new_string("Video generation queued (provider plugin handles async execution)"));
    }
    return result;

/*
     * Pull human-readable caveats out of one model's catalog metadata.
     * Returns a JSON array of caveat strings.
     */
    json_node_t *caveats = json_new_array();
    if (!caveats) return NULL;
    if (!model_meta || !json_node_is_object(model_meta)) {
        return caveats;
    }
    /* Check modalities */
    json_node_t *modalities = json_object_get(model_meta, "modalities");
    json_node_t *modality = json_object_get(model_meta, "modality");
    int has_image = 0, has_text = 0;
    if (modalities && json_node_is_array(modalities)) {
        int n = json_array_count(modalities);
        int i;
        for (i = 0; i < n; i++) {
            json_node_t *m = json_array_get(modalities, i);
            if (json_node_is_string(m)) {
                const char *s = json_node_get_string(m);
                if (strcmp(s, "image") == 0) has_image = 1;
                if (strcmp(s, "text") == 0) has_text = 1;
            }
        }
    }
    if (modality && json_node_is_string(modality)) {
        const char *s = json_node_get_string(modality);
        if (strcmp(s, "image") == 0) has_image = 1;
        if (strcmp(s, "text") == 0) has_text = 1;
    }
    if (has_image && !has_text) {
        json_array_append(caveats, json_new_string(
            "this model is image-to-video only - image_url is REQUIRED; text-only calls will be rejected"));
    } else if (has_text && !has_image) {
        json_array_append(caveats, json_new_string(
            "this model is text-to-video only - image_url is not supported"));
    }
    (void)backend_caps;
    hermes_log(LOG_DEBUG, "video_gen", "_format_model_caveats: %d caveat(s)", json_array_count(caveats));
    return caveats;

/*
     * Build a description that reflects the active backend's actual surface.
     * Falls back to the generic description when no provider is configured.
     */
    json_node_t *schema = json_new_object();
    if (!schema) return NULL;
    const char *generic_desc =
        "Generate a video from a text prompt (text-to-video) or animate a "
        "still image (image-to-video) using the user's configured video "
        "generation backend.";
    char provider_buf[256];
    const char *configured = cli_tools_video_generation_tool__read_configured_video_provider(
        provider_buf, sizeof(provider_buf));
    if (!configured) {
        json_object_set(schema, "description", json_new_string(generic_desc));
        json_object_set(schema, "warning", json_new_string(
            "No video backend is configured. Calls will return an error "
            "until the user picks one via `hermes tools` -> Video Generation."));
        hermes_log(LOG_DEBUG, "video_gen", "_build_dynamic_schema: no provider, using generic desc");
    } else {
        json_object_set(schema, "description", json_new_string(generic_desc));
        json_object_set(schema, "active_backend", json_new_string(configured));
        json_object_set(schema, "status", json_new_string("configured"));
        hermes_log(LOG_DEBUG, "video_gen", "_build_dynamic_schema: backend=%s", configured);
    }
    return schema;

/* In C, we don't have Python audio libraries */
    /* Check for ALSA/PulseAudio on Linux */
#ifndef _WIN32
    /* Check if /dev/snd exists (ALSA) */
    if (access("/dev/snd", F_OK) == 0) {
