if (!text) return 0;
    /* strip */
    while (*text == ' ' || *text == '\t' || *text == '\n' || *text == '\r') text++;
    if (!*text) return 0;

    /* whole response is a token */
    if (cron_token_is_silent(text)) return 1;

    /* first/last non-empty line token */
    /* tokenize into lines, find first & last non-empty (after strip) */
    char *copy = strdup(text);
    char *lines[512];
    int nlines = 0;
    char *p = copy;
    char *start = p;
    while (*p) {
        if (*p == '\n') {
            *p = '\0';
            if (start[0]) { lines[nlines++] = start; }
            p++;
            start = p;
        } else {
            p++;
        }
    }
    if (start[0] && nlines < 512) lines[nlines++] = start;
    if (nlines > 0) {
        if (cron_token_is_silent(lines[0])) { free(copy); return 1; }
        if (cron_token_is_silent(lines[nlines - 1])) { free(copy); return 1; }
    }
    free(copy);

    /* bracketed prefix [SILENT] (case-insensitive) */
    /* check upper-prefix */
    char up[16];
    int k = 0;
    const char *q = text;
    while (*q && k < 15) {
        char c = *q++;
        if (c >= 'a' && c <= 'z') c = (char)(c - 'a' + 'A');
        up[k++] = c;
    }
    up[k] = '\0';
    if (strncmp(up, "[SILENT]", 8) == 0) return 1;
    return 0;

/* Whether this scheduler provider can run in the current environment.
     * The builtin is always available.
     * Port of Python cron/scheduler_provider.py:SchedulerProvider.is_available(). */
    return true;

/* Python: value = getattr(platform, "value", platform);
     *         return str(value or "").lower() */
    const char *value = platform ? platform : "";
    char *out = strdup(value);
    if (!out) return strdup("");
    for (char *p = out; *p; p++)
        *p = (char)tolower((unsigned char)*p);
    return out;

