    if (!result) return NULL;
    const char *src = text;
    char *dst = result;
    bool in_code = false;
    while (*src && (dst - result) < (long)len) {
        if (src[0] == '`' && src[1] == '`') {
            in_code = !in_code;
            src += 2;
        } else if (src[0] == '`' && !in_code) {
            in_code = !in_code;
            src++;
        } else if (!in_code && (src[0] == '#' || src[0] == '*' || src[0] == '_' || src[0] == '[')) {
            /* Skip markdown markers */
            src++;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
    return result;

